async function api(body,attempt=0){if(attempt>1)throw Error('账户会话未能建立，请允许本站 Cookie 后重新连接');const r=await fetch('/api/bank',{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(body?.action==='chat'?120000:25000)});const data=await r.json();if(data.needsSession)return api({action:'init'},attempt+1);if(data.loginComplete)return api(undefined,attempt+1);if(!r.ok){if(data.locked){model=data;render();}throw Error(data.error||'服务暂不可用');}return data;}
async function act(body,success){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');const submittingForm=document.activeElement?.closest('form');submittingForm?.querySelector('.inline-service-error')?.remove();const disabled=new Map([...document.querySelectorAll('button')].map(b=>[b,b.disabled]));disabled.forEach((_,b)=>b.disabled=true);try{model=await api(body);if(model.view)view=model.view;render();if(model.state?.pending)showConfirm();else if(body.action==='confirm'&&model.receipt)showResult(model.receipt);else $('#confirm').close();if(success)toast(success);}catch(e){toast(e.message);const err=$('#modal-error');if(err)err.textContent=e.message;else if(submittingForm?.isConnected){const alert=document.createElement('p');alert.className='error inline-service-error';alert.setAttribute('role','alert');alert.textContent=e.message;submittingForm.append(alert);}}finally{busy=false;document.body.removeAttribute('aria-busy');disabled.forEach((was,b)=>{if(b.isConnected)b.disabled=was;});}}
function flowSteps(step){return `<ol class="flow-steps" aria-label="办理进度">${['填写信息','核对确认','办理结果'].map((x,i)=>`<li ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${x}</li>`).join('')}</ol>`;}
function showResult(r){const plan=model.state.plans.find(x=>x.id===r.planId)||model.state.workflows?.find(x=>x.id===r.workflowId);const label=plan?recordState(plan.status):(r.status||'已完成');$('#confirm-body').innerHTML=`<section class="modal result-modal" aria-labelledby="result-title">${flowSteps(2)}<div class="result-seal">${icon(plan?'clock':'shield')}</div><span class="tag green">${esc(label)}</span><h2 id="result-title">${esc(businessCopy(r.title))}</h2><p>${plan?'计划已保存，实际执行进度请在办理记录中查看。':r.type==='flightCreate'?'订单已建立，尚未扣款。请在机票订单中选择付款卡完成付款。':r.type==='flightPay'?'付款已完成，订单处于出票中。请在机票订单里完成测试出票。':r.type==='loanApply'?'申请结果已保存，尚未放款。通过后请在贷款页面核对合同并签约。':'办理结果已保存，可在办理记录中核对相关入账。'}</p>${r.amount!=null?`<div class="result-amount"><span>${r.type==='subscriptionCreate'?'每期授权金额（元）':r.type==='depositRenewal'?'存单本金（元）':'本次金额（元）'}</span><strong>¥ ${money(r.amount)}</strong></div>`:''}<div class="confirmation-details">${(r.lines||[]).map(x=>`<p>${esc(businessCopy(x))}</p>`).join('')}<p><span>回执编号</span><b>${esc(r.id)}</b></p><p><span>记录时间</span><b>${stamp(r.at)}</b></p></div><p class="modal-disclaimer">测试环境回执，不具有真实银行凭证效力。</p><div class="form-footer">${r.type?.startsWith('loan')?btn('查看借款进度','resultFinance34','','data-view="loans"'):r.type?.startsWith('installment')?btn('查看分期计划','resultFinance34','','data-view="installments"'):''}${btn('查看全部回执','resultRecords')}${btn('完成','close','primary')}</div></section>`;if(!$('#confirm').open)$('#confirm').showModal();$('#confirm-body [data-action=close]')?.focus();}

const selectContacts=(multiple=false)=>multiple?`<div class="checks">${model.contacts.filter(c=>!c.archived).map(c=>`<label><input type="checkbox" name="people" value="${c.id}" checked>${esc(c.name)}</label>`).join('')}</div>`:`<select name="contact" required>${model.contacts.filter(c=>!c.archived).map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.phone)} · ${esc(c.note)}</option>`).join('')}</select>`;
const field=(label,input,help='')=>`<div class="field">${input.startsWith('<div')?`<span>${label}</span>${input}`:`<label>${label}${input}</label>`}${help?`<small>${help}</small>`:''}</div>`;
const title=(name,sub,action='')=>`<header class="heading"><div><h1>${name}</h1><p>${sub}</p></div>${action}</header>`;
const btn=(text,action,cls='',data='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
