function transactions(tx,limit=8){return `<div class="table-wrap"><table><thead><tr><th>交易 / 商户</th><th>日期</th><th>分类</th><th class="amount">金额（元）</th></tr></thead><tbody>${tx.slice(0,limit).map(t=>`<tr><td><div class="merchant"><span class="merchant-icon">${esc(t.category.slice(0,1))}</span><span>${esc(t.merchant)}<span class="sub">${esc(t.note)}</span></span></div></td><td>${date(t.at)}</td><td><span class="tag">${esc(t.category)}</span></td><td class="amount ${t.amount>0?'income':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">这个期间还没有交易记录。</td></tr>'}</tbody></table></div>`;}
function calcReport(){const r=period==='year'?model.yearReport:model.report;return {...r,tx:r.transactions};}
let artDraft=null,uploadSequence=0;
function textControls(c){return `<fieldset class="ink-controls"><legend>卡面文字</legend><label><input type="radio" name="textMode" value="auto" ${c.textMode!=='manual'?'checked':''}> 自动适配</label><label><input type="radio" name="textMode" value="manual" ${c.textMode==='manual'?'checked':''}> 手动选色</label><label class="ink-picker">文字颜色 <input type="color" name="textColor" aria-label="卡面文字颜色" value="${c.textColor||'#ffffff'}"></label><p class="design-hint">自动模式会根据当前图片构图调整深浅，并加上柔和衬底；手动选色会同步应用到卡号、姓名与卡片文字。</p></fieldset>`;}
function adaptCardInk(card){const img=card.querySelector('.card-artwork');if(!img)return;const apply=()=>{if(!card.isConnected)return;let ink=card.dataset.manualInk;try{if(!ink){const canvas=document.createElement('canvas');canvas.width=64;canvas.height=40;const ctx=canvas.getContext('2d',{willReadFrequently:true}),x=parseFloat(img.style.objectPosition)/100,y=parseFloat(img.style.objectPosition.split(' ')[1])/100,z=Number(img.style.transform.match(/[\d.]+/)?.[0]||1),k=Math.max(64/img.naturalWidth,40/img.naturalHeight)*z,w=img.naturalWidth*k,h=img.naturalHeight*k;ctx.drawImage(img,(64-w)*x,(40-h)*y,w,h);ink=chooseCardInk(ctx.getImageData(0,0,64,40).data);}}catch{ink='#ffffff';}card.style.setProperty('--ink',ink);const dark=chooseCardInk(new Uint8ClampedArray([...ink.slice(1).match(/../g).map(v=>parseInt(v,16)),255]))==='#ffffff';card.style.setProperty('--ink-backing',dark?'255,255,255':'0,0,0');card.style.setProperty('--ink-shadow',dark?'rgba(255,255,255,.65)':'rgba(0,0,0,.65)');};if(img.complete&&img.naturalWidth)apply();else img.addEventListener('load',apply,{once:true});}
function adaptAllCardInk(){document.querySelectorAll('.payment-card').forEach(adaptCardInk);}
function artworkLayer(a){return a?`<img class="card-artwork" src="${esc(a.src)}" alt="" draggable="false" style="object-position:${a.x}% ${a.y}%;transform-origin:${a.x}% ${a.y}%;transform:scale(${a.zoom})"><div class="artwork-shade"></div>`:'';}
function artworkControls(){return `<div class="artwork-editor"><label class="upload-label">上传自己的图片<input type="file" id="card-image-upload" accept="image/jpeg,image/png,image/webp"></label><p class="design-hint">JPG、PNG 或 WebP，最大 8 MB。图片在浏览器压缩后，点击保存才上传到当前账户。</p><div id="crop-tools" ${artDraft?'':'hidden'}><p class="design-hint">直接拖动上方卡面调整构图，也可使用下方滑块。</p>${[['zoom','图片缩放',1,3,.01],['x','水平位置',0,100,1],['y','垂直位置',0,100,1]].map(([key,label,min,max,step])=>`<label class="crop-range">${label}<input aria-label="${label}" type="range" data-crop="${key}" min="${min}" max="${max}" step="${step}" value="${artDraft?.[key]??(key==='zoom'?1:50)}"></label>`).join('')}<div class="form-footer"><button type="button" class="btn" id="center-artwork">居中重置</button><button type="button" class="btn" id="remove-artwork">移除图片</button></div></div><p id="upload-status" class="design-hint" role="status"></p></div>`;}
function updateArtworkPreview(){const f=document.querySelector('[data-form="cardDesign"]');if(!f)return;const draft=Object.fromEntries(new FormData(f));$('#card-preview').innerHTML=paymentCard({...model.state,card:{...model.state.card,...draft,artwork:artDraft}},true);$('#crop-tools').hidden=!artDraft;adaptAllCardInk();}
document.addEventListener('change',async e=>{if(e.target.id!=='card-image-upload')return;const file=e.target.files[0];if(!file)return;const seq=++uploadSequence,form=e.target.closest('form'),cardId=model.state.activeCardId;const submit=form.querySelector('[type="submit"]');submit.disabled=true;$('#upload-status').textContent='正在处理图片…';let bitmap;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('请选择 8 MB 以内的 JPG、PNG 或 WebP 图片。');bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000)throw Error('图片尺寸过大，请选择 4000 万像素以内的图片。');const canvas=document.createElement('canvas'),ratio=Math.min(1,768/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let src;for(const quality of [.86,.7,.5,.3]){src=canvas.toDataURL('image/jpeg',quality);if(src.length<=60000)break;}while(src.length>60000&&canvas.width>128){canvas.width=Math.round(canvas.width*.75);canvas.height=Math.max(1,Math.round(canvas.height*.75));ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);src=canvas.toDataURL('image/jpeg',.7);}if(src.length>60000)throw Error('无法压缩这张图片，请换一张图片。');if(seq!==uploadSequence||!form.isConnected||model.state.activeCardId!==cardId)return;artDraft={src,x:50,y:50,zoom:1};updateArtworkPreview();document.querySelectorAll('[data-crop]').forEach(el=>el.value=artDraft[el.dataset.crop]);$('#upload-status').textContent='图片已就绪，调整构图后点击“保存卡面”。';}catch(err){if(form.isConnected)$('#upload-status').textContent=err.message;}finally{bitmap?.close();if(form.isConnected)submit.disabled=false;e.target.value='';}});
document.addEventListener('click',e=>{if(!['center-artwork','remove-artwork'].includes(e.target.id))return;if(e.target.id==='remove-artwork')artDraft=null;else if(artDraft)Object.assign(artDraft,{x:50,y:50,zoom:1});updateArtworkPreview();document.querySelectorAll('[data-crop]').forEach(el=>el.value=artDraft?.[el.dataset.crop]??(el.dataset.crop==='zoom'?1:50));});
let artDrag=null;
document.addEventListener('pointerdown',e=>{const preview=e.target.closest('#card-preview');if(!preview||!artDraft||e.button!==0)return;e.preventDefault();const card=preview.querySelector('.payment-card'),img=card.querySelector('.card-artwork'),r=card.getBoundingClientRect(),cover=Math.max(r.width/img.naturalWidth,r.height/img.naturalHeight);artDrag={id:e.pointerId,preview,startX:e.clientX,startY:e.clientY,x:artDraft.x,y:artDraft.y,overflowX:img.naturalWidth*cover*artDraft.zoom-r.width,overflowY:img.naturalHeight*cover*artDraft.zoom-r.height};preview.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!artDrag||e.pointerId!==artDrag.id)return;const d=artDrag,clamp=v=>Math.max(0,Math.min(100,v));if(d.overflowX>1)artDraft.x=clamp(d.x-(e.clientX-d.startX)/d.overflowX*100);if(d.overflowY>1)artDraft.y=clamp(d.y-(e.clientY-d.startY)/d.overflowY*100);updateArtworkPreview();document.querySelectorAll('[data-crop]').forEach(el=>el.value=artDraft[el.dataset.crop]);});
for(const event of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(event,()=>{artDrag=null;});
function paymentCard(s,compact=false){
 const waves=Array.from({length:24},(_,i)=>`<path d="M ${120+i*8} -20 C ${340+i*5} 65, ${80+i*11} 120, ${370+i*8} 270"/>`).join('');
 return `<div class="payment-card theme-${esc(s.card.theme||'forest')} pattern-${esc(s.card.pattern||'contour')} ${compact?'compact':''} ${s.card.artwork?'has-artwork':''}" data-manual-ink="${s.card.textMode==='manual'?esc(s.card.textColor||'#ffffff'):''}" style="--ink:${s.card.textMode==='manual'?esc(s.card.textColor||'#ffffff'):['champagne','pearl'].includes(s.card.theme)&&!s.card.artwork?'#172c25':'#ffffff'}">${artworkLayer(s.card.artwork)}<svg class="card-guilloche" viewBox="0 0 430 270" aria-hidden="true" fill="none" stroke="currentColor" stroke-width=".55">${waves}</svg><div class="card-light" aria-hidden="true"></div><div class="payment-brand"><span class="card-symbol">银</span><span>个人银行<small>${esc(s.card.nickname||'个人借记卡')} · ${cardType(s.card)}</small></span><svg class="contactless" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M9 8a7 7 0 0 1 0 8m3-11a11 11 0 0 1 0 14m3-17a16 16 0 0 1 0 20"/></svg></div><div class="metal-chip" aria-hidden="true"><i></i></div><div class="payment-number"><span>•••• &nbsp; •••• &nbsp; ••••</span> ${s.card.last4}</div><div class="payment-bottom"><span>${esc(s.profile?.name||'先生')} <small>持卡人</small></span><span>${status(s.card.status)}<i class="card-circles" aria-hidden="true"></i></span></div><button class="card-open" data-action="nav" data-view="cards" aria-label="查看银行卡详情"><span>查看卡片 ${icon('arrow')}</span></button></div>`;
}
function spendingRibbon(s,tx,expense){const days=Array.from({length:14},(_,i)=>{const d=new Date(s.now);d.setDate(d.getDate()-13+i);return {label:date(d),value:tx.filter(t=>date(t.at)===date(d)&&t.amount<0).reduce((sum,t)=>sum-t.amount,0)};}),max=Math.max(1,...days.map(d=>d.value));return `<section class="spending-ribbon" aria-label="近期收支"><div class="spending-summary"><span>本月支出</span><strong>${hideBalance?'••••••':'¥ '+money(expense)}</strong><small>来自当前账本</small></div><div class="spending-chart"><div class="spending-bars">${days.map(d=>`<button data-action="nav" data-view="bills" aria-label="${d.label}支出 ${hideBalance?'金额已隐藏':money(d.value)+' 元'}，查看账单" title="${d.label} · ${hideBalance?'金额已隐藏':'¥ '+money(d.value)}"><i style="height:${hideBalance?12:Math.max(6,d.value/max*100)}%"></i></button>`).join('')}</div><div class="spending-axis"><span>${days[0].label}</span><span>近 14 天</span><span>${days.at(-1).label}</span></div></div><button class="ribbon-link" data-action="nav" data-view="bills"><span>了解你的<br>消费去向</span>${icon('arrow')}</button></section>`;}
function walletGallery(s){const index=s.cards.findIndex(c=>c.id===s.activeCardId);return `<section class="wallet-gallery" aria-label="我的银行卡"><div class="wallet-heading"><span>我的银行卡</span><button class="text-btn" data-action="nav" data-view="cards">定制与管理 ${icon('arrow')}</button></div><div class="wallet-scene" data-wallet-swipe><div class="wallet-plinth" aria-hidden="true"></div><div class="wallet-card-frame" key="${s.card.id}">${paymentCard(s)}</div></div><div class="wallet-caption"><span><strong>${esc(s.card.nickname)}</strong><small><i class="status-dot"></i>${status(s.card.status)} · 尾号 ${s.card.last4}</small></span><div class="wallet-arrows"><button data-action="cycleCard" data-direction="-1" aria-label="上一张银行卡" ${s.cards.length<2?'disabled':''}>${icon('arrow')}</button><button data-action="cycleCard" data-direction="1" aria-label="下一张银行卡" ${s.cards.length<2?'disabled':''}>${icon('arrow')}</button></div></div><div class="wallet-pagination" aria-label="选择银行卡">${s.cards.map((c,i)=>`<button data-action="selectCard" data-id="${c.id}" aria-label="切换到${esc(c.nickname)}，尾号${c.last4}" aria-pressed="${c.id===s.activeCardId}"><span></span></button>`).join('')}<small>${String(index+1).padStart(2,'0')} / ${String(s.cards.length).padStart(2,'0')}</small></div><p class="wallet-footnote">${s.cards.length>1?'左右切换你的银行卡，手机支持滑动。':'你的第一张卡。更多生活场景，可以添加更多卡片。'}</p></section>`;}
function recentReceipts(s,limit=5){return s.transactions.slice(0,limit).map(t=>`<details class="receipt"><summary><span class="receipt-symbol ${t.amount>0?'received':''}">${categoryIcon(t.category,t.amount)}</span><span class="receipt-merchant">${esc(t.merchant)}<small>${date(t.at)} · ${esc(t.category)}</small></span><span class="receipt-amount ${t.amount>0?'income':''}">${hideBalance?'••••••':(t.amount>0?'+':'−')+money(Math.abs(t.amount))}</span><span class="receipt-chevron">${icon('arrow')}</span></summary><div class="receipt-detail"><span>交易状态<strong>${esc(t.status||'已记录')}</strong></span><span>交易编号<strong>${esc(t.id)}</strong></span><span>交易时间<strong>${stamp(t.at)}</strong></span><span>交易备注<strong>${esc(t.note||'无备注')}</strong></span>${t.cardId?`<span>使用卡片<strong>${esc(s.cards.find(c=>c.id===t.cardId)?.nickname||'原卡片')} · 尾号 ${esc(s.cards.find(c=>c.id===t.cardId)?.last4||'未记录')}</strong></span>`:''}<span>手续费<strong>¥${money(t.fee||0)}</strong></span>${btn('下载交易回执','receiptDownload','',`data-id="${t.id}" data-kind="transaction"`)}</div></details>`).join('')||'<p class="empty">还没有收支记录。</p>';}
function accountOverview(){
 const s=model.state,holdings=s.holdings.reduce((n,h)=>n+h.amount,0),assets=s.balance+holdings+depositTotal(s)+assets39(s),monthTx=s.transactions.filter(t=>!['信用卡还款','本人卡间转账','存款','存款支取','贷款放款','贷款还本'].includes(t.category)&&new Date(t.at).getUTCFullYear()===new Date(s.now).getUTCFullYear()&&new Date(t.at).getUTCMonth()===new Date(s.now).getUTCMonth()),income=monthTx.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0),expense=-monthTx.filter(t=>t.amount<0).reduce((n,t)=>n+t.amount,0),cashRatio=s.balance/Math.max(1,assets)*100,subs=s.subscriptions.filter(x=>x.status==='active').sort((a,b)=>a.next-b.next),show=n=>hideBalance?'••••••':money(n);
 return `<header class="personal-welcome"><div class="greeting-avatar" aria-hidden="true">银</div><div><h1>${esc(model.state.profile?.name||'先生')}，欢迎回来。</h1><p><time data-wallclock>${wallClock()}</time>，欢迎回到你的银行。</p></div><span class="personal-demo">个人账户</span></header><div class="personal-hero"><section class="personal-assets" aria-label="我的资产"><div class="asset-label">我的总资产 <span>CNY</span><button class="icon-button" data-action="privacy" aria-label="${hideBalance?'显示':'隐藏'}首页资产金额" aria-pressed="${hideBalance}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>${hideBalance?'<path d="m3 3 18 18"/>':''}</svg></button></div><div class="personal-total" aria-label="总资产 ${hideBalance?'已隐藏':money(assets)+' 元'}"><span class="personal-currency">¥</span><strong>${hideBalance?'••••••':money(assets).split('.')[0]}</strong>${hideBalance?'':`<span class="personal-decimal">.${money(assets).split('.')[1]}</span>`}</div><p class="asset-description">每一份积累，都有清晰的去向。<span>余额、存款与理财本金合计</span></p><div class="personal-breakdown"><div><span>可用余额</span><strong>¥ ${show(s.balance-s.reserved)}</strong></div><div><span>理财本金</span><strong>¥ ${show(holdings)}</strong></div><div><span>计划预留</span><strong>¥ ${show(s.reserved)}</strong></div></div><div class="personal-actions"><button class="btn primary" data-action="nav" data-view="transfer">转账汇款 ${icon('arrow')}</button><button class="btn" data-action="nav" data-view="bills">查看账单 ${icon('bills')}</button></div><div class="personal-assurance"><i></i>资产信息仅向当前账户展示</div></section>${walletGallery(s)}</div>
 <nav class="personal-services" aria-label="常用服务">${[['transfer','转账与收款','向熟悉的人，安心转出'],['invest','理财中心','了解风险，再做选择'],['subscriptions','订阅与代扣','让每次续费，都有准备'],['plans','联动计划','提前安排，重要的日子']].map(([k,n,d])=>`<button data-action="nav" data-view="${k}"><span class="personal-service-icon">${icon(k)}</span><span><strong>${n}</strong><small>${d}</small></span><span class="service-arrow">${icon('arrow')}</span></button>`).join('')}</nav>
 <div class="personal-lower"><section class="personal-activity"><div class="personal-section-heading"><div><h2>最近的资金往来</h2><p>点开一笔记录，查看交易详情。</p></div><button class="text-btn" data-action="nav" data-view="bills">全部账单 ${icon('arrow')}</button></div><div class="receipt-list">${recentReceipts(s)}</div></section><section class="personal-month"><div class="personal-section-heading"><div><h2>这个月，花在哪里</h2><p>来自当前账本</p></div></div><div class="month-numbers"><div><span>收入</span><strong>+ ${show(income)}</strong></div><div><span>支出</span><strong>− ${show(expense)}</strong></div></div>${spendingRibbon(s,s.transactions.filter(t=>!['信用卡还款','本人卡间转账','存款','存款支取','贷款放款','贷款还本'].includes(t.category)),expense)}<button class="month-composition" data-action="nav" data-view="invest"><span>账户余额 / 理财本金</span><div class="composition-track" aria-hidden="true"><i style="width:${hideBalance?50:cashRatio}%"></i></div><span><b>${hideBalance?'••••':cashRatio.toFixed(1)+'%'}</b><small>了解资产配置 ${icon('arrow')}</small></span></button></section></div>
 <section class="personal-concierge"><div class="concierge-mark" aria-hidden="true">${icon('spark')}</div><div><h2>需要的时候，银行助手就在。</h2><p>查账单、准备转账，或者安排一份计划。</p></div><button class="btn" data-action="assistant">与银行助手对话 ${icon('arrow')}</button></section><section class="personal-reminders"><div class="personal-section-heading"><h2>接下来的安排</h2><button class="text-btn" data-action="nav" data-view="subscriptions">管理订阅 ${icon('arrow')}</button></div><div>${subs.slice(0,2).map(x=>`<button data-action="nav" data-view="subscriptions"><span class="reminder-calendar">${date(x.next)}</span><span><strong>${esc(x.name)}续费</strong><small>代扣 · 可提前取消</small></span><b>${hideBalance?'••••••':'¥ '+money(x.amount)}</b>${icon('arrow')}</button>`).join('')||'<p class="empty">近期没有有效订阅。</p>'}</div></section>`;
}
function transfer(){const s=model.state;return title('转账与收款','选择熟悉的人，安排一笔转账。')+`${ownTransferForm(s)}<details class="plan-composer"><summary>直接转入银行卡 <span>无需保存收款人 ${icon('arrow')}</span></summary><form data-form="bankTransfer" class="contact-form"><p>请核对收款人信息；测试环境不核验真实银行账户。</p><div class="form-grid">${field('收款人姓名','<input name="name" maxlength="24" required>')}${field('收款银行','<input name="bank" maxlength="40" required>')}${field('银行卡号','<input name="account" inputmode="numeric" pattern="[0-9]{12,19}" maxlength="19" required>')}${field('转账金额（元）','<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required>')}</div><button class="btn primary">核对银行卡转账</button></form></details><div class="journey-tabs tabs"><button data-action="transferTab" data-tab="transfer" class="${transferTab==='transfer'?'selected':''}">转账给他人</button><button data-action="transferTab" data-tab="split" class="${transferTab==='split'?'selected':''}">一起分摊 · AA</button></div><div class="transfer-journey"><section class="transfer-compose">${transferTab==='transfer'?`<form data-form="transfer"><fieldset class="recipient-choice"><legend>转给谁</legend><p>选择已保存收款人，或先添加银行卡。${btn('添加银行卡收款人','nav','','data-view=contacts')}</p><div>${model.contacts.filter(c=>!c.archived).map((c,i)=>`<label><input type="radio" name="contact" value="${c.id}" ${(selectedRecipient?c.id===selectedRecipient:i===0)?'checked':''} required><span class="recipient-avatar">${esc(c.name.slice(0,1))}</span><strong>${esc(c.name)}</strong><small>${esc(c.note)} · ${c.phone}</small></label>`).join('')}</div></fieldset><label class="transfer-amount">转账金额<span><b>¥</b><input name="amount" aria-label="转账金额（元）" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" placeholder="0.00" required></span></label><p class="transfer-available">可用余额 <strong>¥ ${money(s.card.available||0)}</strong></p><details class="schedule-choice"><summary>${icon('clock')} 预约转账 <span>选填</span></summary>${field('预约时间','<input type="datetime-local" name="at">','留空立即执行。预约将预留资金，时间以浏览器本地时区为准。')}</details><div class="transfer-submit"><button class="btn primary" type="submit">下一步，核对信息 ${icon('arrow')}</button><p>下一步会展示收款人、金额与时间，确认后才执行。</p></div></form>`:`<form data-form="split"><label class="transfer-amount">这笔账单一共多少<span><b>¥</b><input name="amount" aria-label="账单总金额（元）" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0.00" required></span></label>${field('和谁一起分摊',selectContacts(true),'总人数包含你本人，不能整除的分由发起人承担。')}<button class="btn primary">生成 AA 收款单 ${icon('arrow')}</button></form>`}</section><aside class="transfer-pocket"><span class="pocket-label">本次使用</span><div class="pocket-card">${paymentCard(s,true)}</div><h2>${esc(s.card.nickname)}</h2><p>尾号 ${s.card.last4} · ${status(s.card.status)}</p><dl><div><dt>单笔限额</dt><dd>¥ ${money(s.card.limit)}</dd></div><div><dt>本卡余额</dt><dd>¥ ${money(s.card.balance||0)}</dd></div></dl><button class="text-btn" data-action="nav" data-view="cards">管理付款卡 ${icon('arrow')}</button><div class="transfer-guidance">${model.testMode?'测试模式免密码，核对后确认即可。':'每笔转账均须输入独立转账密码确认。'}</div></aside></div>${transferTab==='split'?`<section class="split-history"><h2>我的收款单</h2>${s.splits.map(x=>`<details class="split-receipt"><summary><strong>AA 收款 ¥${money(x.amount)}</strong><span>${date(x.at)} · 待朋友支付</span></summary><p>本人承担 ¥${money(x.self)}</p>${x.participants.map(p=>`<p>${esc(model.contacts.find(c=>c.id===p.contact).name)} · ¥${money(p.amount)} · ${esc(p.status)} ${p.status==='待支付'?btn('朋友支付','splitCollect','',`data-split="${x.id}" data-contact="${p.contact}"`):''}</p>`).join('')}</details>`).join('')||'<p class="empty">创建收款单后，在这里查看每个人的分摊金额。</p>'}</section>`:''}`;}
function bills(){const r=calcReport(),max=Math.max(1,...Object.values(r.groups)),filtered=r.tx.filter(t=>billFilter==='all'||(billFilter==='income'?t.amount>0&&!/退款/.test(t.category):t.amount<0&&t.category===billFilter));return title('账单分析','看清每一笔，也看见生活的节奏。',btn(`${icon('download')}导出完整账单`,'export'))+`<div class="statement-overview"><section><div class="tabs"><button data-action="period" data-period="month" class="${period==='month'?'selected':''}">本月</button><button data-action="period" data-period="year" class="${period==='year'?'selected':''}">本年</button></div><span class="statement-label">${period==='month'?'本月':'本年'}总支出</span><div class="statement-total">¥ ${money(r.expense)}</div><div class="statement-flow"><span>收入<strong>+ ${money(r.income)}</strong></span><span>退款返还<strong>${money(r.refunds||0)}</strong></span><span>收支结余<strong>${money(r.income-r.expense+(r.refunds||0))}</strong></span></div></section><section class="statement-distribution"><h2>消费去向</h2><p>点击分类，查看对应的交易。</p>${Object.entries(r.groups).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<button data-action="billFilter" data-filter="${esc(k)}" aria-pressed="${billFilter===k}"><span>${esc(k)}<strong>¥ ${money(v)}</strong></span><i><b style="width:${v/max*100}%"></b></i></button>`).join('')||'<p class="empty">这个期间还没有支出。</p>'}</section></div><section class="statement-records"><div class="personal-section-heading"><h2>资金往来</h2><span>${filtered.length} 笔</span></div><div class="statement-filters" aria-label="交易分类">${[['all','全部'],['income','收入'],...Object.keys(r.groups).map(k=>[k,k])].map(([k,n])=>`<button data-action="billFilter" data-filter="${esc(k)}" aria-pressed="${billFilter===k}">${esc(n)}</button>`).join('')}</div>${recentReceipts({...model.state,transactions:filtered},filtered.length)}</section><details class="statement-checks"><summary>${icon('shield')} 待核实交易 <span>${r.anomalies.length} 笔</span></summary>${r.anomalies.map(t=>`<div class="insight"><div><strong>${esc(t.merchant)} · ¥${money(-t.amount)}</strong><p>${esc(t.reason)}</p></div></div>`).join('')||'<p>当前没有待核实交易。</p>'}</details>`;}
function invest(){const s=model.state,validRisk=!!s.riskAssessment&&s.now-s.riskAt<=365*86400000;return wealthHeader()+title('理财产品','先了解自己，再选择适合的配置。')+investmentComparison()+`<section class="investment-intro"><div><span>我的理财本金</span><strong>¥ ${money(s.holdings.filter(h=>!['gold','deposit'].includes(h.product)).reduce((sum,h)=>sum+h.amount,0))}</strong><p>请了解产品期限与风险，再作投资决定。</p></div><div><span>风险承受等级</span><strong>${validRisk?'R'+s.risk:'需更新评估'}</strong><p>选择产品前，先完成下方评估。</p></div></section><details class="risk-disclosure"><summary>风险承受能力评估 <span>${s.risk?'重新评估':'开始评估'} ${icon('arrow')}</span></summary><section class="risk-content"><div class="panel-title"><h2>风险承受能力评估</h2><span class="tag ${s.risk?'green':'amber'}">${s.risk?'当前 R'+s.risk:'待评估'}</span></div><form data-form="risk" class="risk-questionnaire"><p>共 10 项。请按实际情况选择；此为测试规则，不替代银行正式适当性评估。</p>${riskQuestions.map((q,i)=>field((i+1)+'. '+q[0],`<select name="q${i}" required><option value="">请选择</option>${q[1].map((v,j)=>`<option value="${j+1}">${v}</option>`).join('')}</select>`)).join('')}<button class="btn primary">提交评估</button>${s.riskAssessment?`<p>上次得分 ${s.riskAssessment.score}/50 · ${esc(s.riskAssessment.explanation)} 有效期一年。</p>`:''}</form></section></details><section class="investment-products"><div class="panel-title"><h2>了解一份产品</h2><span class="muted small">适配评估等级，不追求收益排名</span></div>${model.products.filter(p=>!['gold','deposit'].includes(p.id)).filter(p=>wealthCategory==='all'||(wealthCategory==='liquid'?p.days===0:wealthCategory==='term'?p.days>0:wealthCategory==='gold'?p.id==='gold':p.risk<=2)).map(p=>`<article class="product investment-product"><div class="product-head"><h3>${businessCopy(p.name)}</h3><span class="tag ${validRisk&&s.risk>=p.risk?'green':'amber'}">R${p.risk} · ${validRisk&&s.risk>=p.risk?'风险匹配':'暂不匹配'}</span></div><div class="product-spec"><div>业绩参考<strong>${p.rate}</strong></div><div>持有期<strong>${p.days?p.days+' 天':'灵活'}</strong></div><div>起购金额<strong>¥${money(p.min)}</strong></div></div><p>${businessCopy(p.description)}</p><details class="product-purchase"><summary>${validRisk&&s.risk>=p.risk?'准备申购':'查看申购条件'} ${icon('arrow')}</summary><p class="purchase-condition">${validRisk&&s.risk>=p.risk?'你的风险等级与此产品匹配。':'请先在上方完成评估，风险等级匹配后才能申购。'}</p><form data-form="buy" data-product="${p.id}"><div class="form-footer"><input aria-label="${businessCopy(p.name)}申购金额" name="amount" type="number" min="${p.min/100}" step="0.01" placeholder="申购金额（元）" required style="padding:10px;border:1px solid #dce4ef;border-radius:6px;max-width:180px"> <button class="btn ${validRisk&&s.risk>=p.risk?'primary':''}">核对申购</button></div></form></details></article>`).join('')}</section><section class="investment-holdings"><div class="panel-title"><h2>我的持仓</h2><span class="muted small">按本金展示</span></div>${s.holdings.filter(h=>!['gold','deposit'].includes(h.product)).map(h=>`<div class="subscription"><span class="merchant-icon">持</span><div><h3>${model.products.find(p=>p.id===h.product).name}</h3><p>本金 ¥${money(h.amount)} · ${h.unlock>s.now?'到期 '+date(h.unlock):'可赎回'}</p></div>${btn('赎回','redeem','',`data-id="${h.id}"`)}</div>`).join('')||'<p class="empty">暂无理财持仓。</p>'}</section>`;}
const cardThemes=[['forest','墨绿'],['midnight','深海蓝'],['graphite','石墨黑'],['champagne','香槟金'],['pearl','珍珠银']];
function cardSelector(s){return `<label class="card-selector">当前使用卡片<select name="activeCard" aria-label="选择当前卡片">${s.cards.map(c=>`<option value="${c.id}" ${c.id===s.activeCardId?'selected':''}>${esc(c.nickname)} · ${c.last4} · ${status(c.status)}</option>`).join('')}</select></label>`;}
function cards(){const s=model.state,c=s.card;artDraft=c.artwork?{...c.artwork}:null;return title('我的卡包','每张卡都有自己的名字、卡面与交易设置。',btn('添加卡','cardCatalog','primary'))+`${cardCatalog()}<div class="wallet-strip" aria-label="我的卡片">${s.cards.map(x=>`<button class="wallet-item ${x.id===c.id?'selected':''}" data-action="selectCard" data-id="${x.id}" aria-pressed="${x.id===c.id}"><span class="mini-card theme-${x.theme}">${icon('cards')}</span><span><strong>${esc(x.nickname)}</strong><small>尾号 ${x.last4} · ${status(x.status)} · ${x.kind==='debit'?'余额 ¥'+money(x.balance||0):'信用卡'}</small></span>${x.id===c.id?'<span class="wallet-current">当前使用</span>':''}</button>`).join('')}</div><p class="wallet-note">${s.cards.length} / 8 张卡 · 借记卡余额与预留资金分别记账，信用卡消费与欠款独立记账；切换卡片不会转移资金。已确认的预约与代扣仍使用原绑定卡。</p>${cardBusiness(s,c)}<div class="card-workspace"><section class="card-studio card-showroom"><div class="panel-title"><h2>卡面设计</h2><span class="tag">保存后自动应用</span></div><div id="card-preview">${paymentCard(s,true)}</div><details class="card-customization"><summary>定制这张卡 <span>图片、颜色与文字 ${icon('arrow')}</span></summary><form data-form="cardDesign" class="design-form">${artworkControls()}${textControls(c)}${field('卡片昵称',`<input name="nickname" value="${esc(c.nickname)}" maxlength="16" required placeholder="例如：日常生活卡">`)}<fieldset class="theme-options"><legend>卡面颜色</legend>${cardThemes.map(([id,name])=>`<label><input type="radio" name="theme" value="${id}" ${c.theme===id?'checked':''}><span class="color-swatch theme-${id}"></span><span>${name}</span></label>`).join('')}</fieldset>${field('表面纹理',`<select name="pattern"><option value="contour" ${c.pattern==='contour'?'selected':''}>弧线雕纹</option><option value="brushed" ${c.pattern==='brushed'?'selected':''}>拉丝金属</option><option value="minimal" ${c.pattern==='minimal'?'selected':''}>极简素面</option></select>`)}<div class="form-footer"><button class="btn primary" type="submit">保存卡面</button>${btn('恢复已保存样式','resetDesign')}</div><p class="design-hint">上方实时预览。卡面仅改变外观，不影响余额、限额或交易权限。</p></form></details></section><section class="card-control-room"><div class="panel-title"><h2>当前卡片设置</h2><span class="tag ${c.status==='active'?'green':'red'}">${status(c.status)}</span></div><p class="selected-card-name">${esc(c.nickname)} <span>尾号 ${c.last4}</span></p><div class="card-limit-display"><span>单笔交易限额</span><strong>¥ ${money(c.limit)}</strong></div><details class="card-limit-editor"><summary>调整单笔限额 ${icon('arrow')}</summary><form data-form="limit">${field('单笔交易限额（元）',`<input type="number" name="limit" value="${c.limit/100}" min="0.01" step="0.01" required>`)}<button class="btn">更新限额</button></form></details><dl class="detail-list"><div><dt>线上代扣</dt><dd>${c.online?'已允许':'已关闭'}</dd></div><div><dt>${c.kind==='credit'?'可用授信':'可用账户余额'}</dt><dd>¥${money(c.kind==='credit'?Math.max(0,(c.creditLimit||0)-(c.outstanding||0)):c.available||0)}</dd></div></dl><div class="card-actions">${btn(c.online?'关闭线上代扣':'开启线上代扣','online')}${c.status!=='lost'?btn(c.status==='locked'?'解锁卡片':'锁定卡片','card','',`data-op="${c.status==='locked'?'unlock':'lock'}"`):''}${c.status==='lost'?btn('补办卡','card','','data-op="replace"'):btn('挂失','card','danger','data-op="lost"')}</div><div class="notice">这里只修改尾号 ${c.last4} 的卡片。挂失卡需要补办才能恢复。交易执行前仍会检查绑定卡的状态与限额。</div><details class="card-history"><summary>本卡申请记录 <span>${c.applications.length} 条</span></summary>${c.applications.map(x=>`<div class="insight"><span class="merchant-icon">卡</span><div><strong>${esc(x.status)}</strong><p>${stamp(x.at)}</p></div></div>`).join('')||'<p class="empty">暂无申请记录。添加卡片为开卡，不采集身份证件。</p>'}</details></section></div>`;}
function subscriptions(){const s=model.state,active=s.subscriptions.filter(x=>x.status==='active'),total=active.reduce((n,x)=>n+Math.round(x.amount*30/(x.periodDays||30)),0),next=[...active].sort((a,b)=>a.next-b.next)[0],items=s.subscriptions.filter(x=>subscriptionFilter==='all'||(subscriptionFilter==='active'?x.status==='active':x.status!=='active')).sort((a,b)=>a.next-b.next);return title('订阅与代扣','每一次续费，都提前心中有数。')+subscriptionDiscovery()+`<section class="subscription-outlook"><div><span>折算每30天支出</span><strong>¥ ${money(total)}</strong><p>${active.length} 项有效订阅 · 按周期折算每365天约 ¥${money(Math.round(total*365/30))}</p></div><div class="next-renewal"><span>下一笔预计扣款</span>${next?`<strong>${date(next.next)}</strong><p>${esc(next.name)} · ¥${money(next.amount)}</p>`:'<strong>暂无</strong><p>目前没有有效订阅。</p>'}</div></section><div class="subscription-filters statement-filters" aria-label="订阅状态">${[['all','全部订阅'],['active','有效授权'],['paused','已取消授权']].map(([id,label])=>`<button data-action="subscriptionFilter" data-filter="${id}" aria-pressed="${subscriptionFilter===id}">${label}</button>`).join('')}</div><section class="renewal-list" aria-label="订阅与授权">${items.map(x=>`<details class="renewal-item"><summary><span class="renewal-symbol">${esc(x.name.slice(0,1))}</span><span class="renewal-name"><strong>${esc(x.name)}</strong><small>${x.status==='active'?'下次 '+date(x.next):x.status==='observed'?'仅记录提醒':'授权已取消'} · ${x.remind?'站内提醒已开启':'站内提醒已关闭'}</small></span><span class="renewal-price">¥${money(x.amount)}<small>/ ${x.periodDays||30} 天</small></span><span class="renewal-chevron">${icon('arrow')}</span></summary><div class="renewal-detail"><div><span>绑定卡片</span><strong>${esc(s.cards.find(c=>c.id===x.cardId)?.nickname||'原卡片')} · ${s.cards.find(c=>c.id===x.cardId)?.last4||''}</strong><p>识别依据：账单商户名称与订阅名单一致。</p></div><div class="renewal-actions">${btn('更换扣款卡','subscriptionCard32','',`data-id="${x.id}"`)}${btn(x.status==='active'?'取消代扣':x.status==='observed'?'确认代扣授权':'恢复代扣','sub',x.status==='active'?'':'primary',`data-id="${x.id}" data-op="${x.status==='active'?'cancel':'resume'}"`)}${btn(x.remind?'关闭站内提醒':'开启站内提醒','sub','',`data-id="${x.id}" data-op="remind"`)}</div></div></details>`).join('')||'<p class="empty">这个分类下暂时没有订阅。</p>'}</section><p class="journey-footnote">提醒仅展示在本站。查看授权状态与下次扣款时间。</p>`;}
function plans(){return journeys66(model,{esc,money})+`<details><summary>其他提醒与原有计划</summary>${legacyPlans66()}</details>`;}
function legacyPlans66(){const s=model.state,upcoming=s.plans.filter(p=>['scheduled','ready','paused'].includes(p.status)),records=[...s.plans].sort((a,b)=>b.at-a.at);return lifestyle64(model,{esc,field},'plans')+title('联动计划','为重要的日子，提前留一份安排。',btn('自动预订与任务执行','nav','primary','data-view=tasks'))+`<section class="planning-outlook"><div><span>待执行计划</span><strong>${upcoming.length}<small> 项</small></strong><p>活动安排与预约转账</p></div><div><span>已预留预算</span><strong>¥ ${money(s.reserved)}</strong><p>计划取消后，预留资金将释放。</p></div></section><details class="plan-composer"><summary><span>${icon('plans')} 创建活动计划</span><span>选择场景、预算与时间 ${icon('arrow')}</span></summary><div class="plan-compose-body"><form data-form="event" class="event-form">${eventFields()}<p class="small muted">预算只预留，不自动购买门票或商品。到期后展示提醒，需你自行核实并付款。请勿输入真实身份或支付信息。</p><button class="btn primary">核对活动计划 ${icon('arrow')}</button></form></div></details><section class="plan-timeline"><div class="personal-section-heading"><h2>你的安排</h2><span>${records.length} 项记录</span></div>${records.map(p=>`<article class="timeline-event"><div class="timeline-date"><strong>${date(p.at)}</strong><span>${status(p.status)}</span></div><details class="timeline-record"><summary><span><strong>${esc(businessCopy(p.title))}</strong><small>${stamp(p.at)}</small></span><b>¥${money(p.amount)}</b>${icon('arrow')}</summary><div class="timeline-detail"><ol>${p.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>${p.orders?.map(o=>`<p>${esc(o.service)} · ¥${money(o.amount)} · ${esc(o.status)} · ${o.id.slice(0,8)}</p>`).join('')||''}${eventEditor(p)}${['scheduled','ready','paused'].includes(p.status)?btn('取消并释放资金','cancelPlan','',`data-id="${p.id}"`):''}</div></details></article>`).join('')||'<div class="planning-empty"><span>'+icon('plans')+'</span><h3>下一份心意，从这里开始。</h3><p>创建活动计划后，可查看预算预留、执行步骤和结果。预约转账也会显示在这里。</p></div>'}</section><details class="simulation-clock"><summary>测试时钟 <span>当前 ${stamp(s.now)} ${icon('clock')}</span></summary><p>本版由你手动推进测试时间。推进会执行到期计划和一次订阅周期，不会补扣跳过的历史周期。</p><div class="card-actions">${[1,7,30,90].map(d=>btn(`推进 ${d} 天`,'clock','',`data-days="${d}"`)).join('')}</div></details>`;}
function security(){const s=model.state;return title('安全中心','权限分级、确认凭证与执行结果集中查看。')+`<div class="metric-row"><div class="metric"><span>已记录操作</span><b>${s.audit.length}</b></div><div class="metric"><span>安全拒绝</span><b>${s.blocked}</b></div><div class="metric"><span>已确认回执</span><b>${s.receipts.length}</b></div></div><section class="panel"><div class="panel-title"><h2>测试环境边界</h2><span class="tag amber">比赛沙箱</span></div><ul class="checklist"><li>非测试模式解锁后才返回账本；资金操作须交易密码与已配置的多因子验证，解锁十分钟后失效。</li><li>登录与交易密码独立设置；服务端分别加盐哈希保存，不使用短信找回；持久账户可使用预先保存的恢复码恢复。</li><li>未连接本地模型时使用规则助手；可配对本地模型提出单步或分步草案，每一步均需独立确认，不调用付费模型。</li><li>持久账号支持跨设备登录；会话到期不删除账户，旧浏览器账户需要迁移。</li><li>活动到期先提醒，付款需另行确认；测试时钟可用于检验到期流程。</li><li>确认单十分钟过期，重复确认不会重复记账，并发冲突会拒绝写入。</li></ul>${btn('重置我的账户','reset','danger')}</section><section class="panel section"><div class="panel-title"><h2>操作审计</h2><span class="muted small">保留最近 160 条</span></div>${s.audit.map(x=>`<div class="audit-row"><time>${date(x.at)} ${new Date(x.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time><span class="tag ${x.type==='拦截'?'red':''}">${x.type}</span><span>${esc(x.text)}</span></div>`).join('')}</section>`;}
function assistant(){const s=model.state;return `<aside class="assistant" role="dialog" aria-modal="true" aria-label="金融助手"><div class="assistant-head"><span class="assistant-logo">${icon('spark')}</span><div><strong>银行助手</strong><small><span class="status-dot"></span>${model.cloudAI?(model.cloudProvider==='glm-free'?'云端 AI · GLM-5.3-Flash':'云端 AI · Cloudflare'):s.ai?.expires>Date.now()?'本地模型通道 · 等待本机运行':'规则助手 · 本地模型未连接'}</small></div><button class="assistant-close icon-button" data-action="assistantClose" aria-label="收起金融助手">×</button></div>${aiControls33()}${s.ai?.navigation?btn('打开业务页面','aiNavigate62','primary',`data-view="${esc(s.ai.navigation.page)}"`):''}<div class="chat" id="chat-log" aria-live="polite">${s.messages.length?s.messages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join(''):`<div class="bubble"><strong>你好，我是银行助手。</strong>可以帮你查航班、准备虚拟订票，办理转账、生活购物与退款，以及理财、存款和贷款还款。<br><br>涉及资金或卡片的操作，我会先列出明细，等你确认。</div>`}</div><div class="suggestions">${['我有哪些银行卡，可用余额多少','帮我订张机票','查看理财产品','查询生活订单并申请退款','查看待还款项'].map(x=>`<button data-action="suggest" data-text="${x}">${x}</button>`).join('')}</div><form class="chat-compose" data-form="chat"><label class="hide" for="chat-input">输入金融需求</label><textarea id="chat-input" name="text" placeholder="例如：帮我取消云音乐订阅" maxlength="1200" required></textarea><div class="compose-footer"><small>Enter 发送 · Shift + Enter 换行</small><button class="btn primary" type="submit" aria-label="发送消息">发送 ${icon('arrow')}</button></div></form><div class="chat-foot">仅使用虚构数据。不连接真实银行，不执行真实转账。${s.pending?'<button class="link-btn" data-action="pending">查看待确认操作</button>':''}</div></aside>`;}

const riskQuestions=[
 ['年龄与资金阶段',['退休且依赖投资资金生活','临近退休','主要用于家庭长期储备','收入稳定的积累阶段','年轻且有独立长期资金']],
 ['投资知识',['不了解金融产品','了解存款与利息','了解债券及净值','了解基金及股票','理解衍生品及复杂风险']],
 ['投资经验',['无经验','不足一年','1–3 年','3–5 年','5 年以上']],
 ['稳定收入与负债压力',['无稳定收入或偿债压力较大','收入波动且负债较高','基本覆盖生活与负债','有稳定结余','稳定结余且负债很低']],
 ['这笔资金多久会用到',['一个月内','三个月内','一年内','1–3 年','三年以上']],
 ['应急资金储备',['没有独立应急金','不足三个月开支','3–6 个月开支','6–12 个月开支','超过一年开支']],
 ['可承受的最大本金损失',['不能接受损失','不超过 5%','不超过 10%','不超过 20%','可以超过 20%']],
 ['本次资金占可投资资产比例',['超过 80%','50%–80%','30%–50%','10%–30%','低于 10%']],
 ['主要投资目标',['保持本金稳定','低波动积累','平衡增长与波动','追求较高长期增长','愿承受高波动寻求增长']],
 ['遇到明显亏损时的反应',['立即退出且无法接受','减少大部分投资','重新评估后适当调整','接受计划内波动','有能力承受并长期观察']]
];
function passwordField(label,name,auto='new-password'){return field(label,`<input name="${name}" type="password" minlength="12" maxlength="128" autocomplete="${auto}" required>`);}

function paymentField(label,name,legacy=false){return field(label,`<input name="${name}" type="password" ${legacy?'minlength="1" maxlength="128"':'inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6"'} autocomplete="off" required>`,legacy?'请输入当前旧转账密码，可在个人中心改为 6 位数字。':'请输入 6 位数字，开头的 0 会保留。');}
function authPasswords(legacy=false){return passwordField('登录密码','loginPassword')+passwordField('再次输入登录密码','loginConfirm')+paymentField('转账密码','paymentPassword',legacy)+paymentField('再次输入转账密码','paymentConfirm',legacy);}
function accountNameField(){return field('账号',`<input name="username" autocomplete="username" pattern="[a-z][a-z0-9_]{5,31}" minlength="6" maxlength="32" value="${esc(model.account||'')}" required>`,'6–32 位小写字母、数字或下划线，以字母开头。');}
function lockScreen(){if(authMode==='test'&&!model.recoveryKey)return `<main class="vault-entry"><span class="tag">测试模式</span><h1>直接开始体验</h1><p>无需注册、登录或设置交易密码。测试使用独立的虚构账户，不改变已有账户及密码。</p>${btn('开启测试模式','enterTest','primary')} ${btn('关闭测试，使用密码登录','passwordMode')}<p class="small">进入后可随时通过顶部开关恢复密码验证。</p></main>`;if(model.recoveryKey)return `<main class="vault-entry"><h1>请保存恢复密钥</h1><p>账号：${esc(model.account)}</p><p>这是找回账户的唯一凭证，仅此刻展示。请保存在你的密码管理器或安全的离线位置；不要发送给其他人。</p><label>恢复密钥<textarea readonly rows="3">${esc(model.recoveryKey)}</textarea></label><p>找回成功后密钥会轮换，旧密钥失效。此站点不发送短信或邮件。</p>${btn('我已保存，前往登录','recoverySaved','primary')}</main>`;
 if(authMode==='legacy'&&!model.accountMode)return legacyLockScreen();
 const mode=authMode==='legacy'?'login':authMode;
 return `<main class="vault-entry">${btn('开启测试模式','enterTest','','role="switch" aria-checked="false"')}<a href="/">MANNENZAKURA</a><div class="vault-emblem">${icon('shield')}</div><p>个人银行 · 持久账户</p><h1>${mode==='register'?'建立你的个人账户':mode==='recover'?'找回账户':'先生，欢迎回来。'}</h1><p>登录会话到期后重新登录即可，账本、卡面与计划继续保留，支持跨设备访问。</p><div class="tabs">${[['login','登录'],['register','注册'],['recover','找回密码']].map(([id,label])=>`<button type="button" data-action="authMode" data-mode="${id}" class="${mode===id?'selected':''}">${label}</button>`).join('')}</div><form data-form="accountAuth" data-mode="${mode}">${accountNameField()}${mode==='login'?passwordField('登录密码','password','current-password'):(mode==='recover'?field('恢复密钥','<input name="recoveryKey" autocomplete="off" minlength="48" maxlength="48" required>'):'')+authPasswords()}${mode!=='login'?'<p>登录密码仍为 12–128 位，包含字母和数字；转账密码为 6 位数字。请使用本站专用密码。</p>':''}<button class="btn primary">${mode==='login'?'登录个人银行':mode==='register'?'注册并生成恢复密钥':'重设密码并轮换恢复密钥'}</button></form><small>注册与找回均不收取费用。<br>恢复密钥丢失且忘记密码时，暂不提供人工找回。</small>${!model.accountMode?btn('访问旧浏览器账户，迁移原有数据','authMode','','data-mode="legacy"'):''}</main>`;}
function migrationForm(){return `<details class="password-setting"><summary>迁移为持久账户 ${icon('arrow')}</summary><p>设置一个账号，并填写旧账户现有的两套密码。迁移后可跨设备登录，原账本和卡面保留。</p><form data-form="accountAuth" data-mode="register" data-migrate="true">${accountNameField()}${authPasswords(true)}<button class="btn primary">迁移并生成恢复密钥</button></form></details>`;}
function legacyLockScreen(){const setup=model.needsSetup;return `<main class="vault-entry">${btn('开启测试模式','enterTest','','role="switch" aria-checked="false"')}<a href="/">MANNENZAKURA</a><div class="vault-emblem">${icon('shield')}</div><p>个人银行</p><h1>${setup?'设置你的银行密码':'欢迎回来。'}</h1><p>${setup?'分别设置登录密码和转账密码。原有账本、卡面和计划会保留。':'输入登录密码，查看资产与账本。转账时使用另一套独立密码。'}</p><form data-form="${setup?'setupPasswords':'unlock'}">${setup?passwordField('登录密码','loginPassword')+passwordField('再次输入登录密码','loginConfirm')+paymentField('转账密码','paymentPassword')+paymentField('再次输入转账密码','paymentConfirm'):passwordField('登录密码','password','current-password')}<p class="small">${setup?'登录密码为 12–128 位字母数字组合，转账密码为 6 位数字。请使用此站点专用密码。':''}</p><button class="btn primary">${setup?'保存两套密码':'登录个人银行'} ${icon('arrow')}</button></form><small>这是当前浏览器的账户，尚不支持跨设备登录与密码找回。<br>会话 Cookie 有效期 7 天；清除 Cookie 或过期后会建立新账户。<br>登录 10 分钟后自动锁定，连续 5 次密码错误暂停验证 5 分钟。</small></main>`;}
function profile(){return lifestyle64(model,{esc,field})+profileLegacy64();}
function profileLegacy64(){if(model.testMode)return personalHub()+ title('个人中心','管理账户与验证方式。')+`<section class="panel"><h2>免密码测试已开启</h2><p>资产查看和交易确认无需密码，交易仍需核对后确认。测试账本与已有个人账户隔离。</p>${btn('关闭测试，启用密码登录','exitTest','primary')}<p>关闭后可登录原账户，或注册并设置独立登录密码与 6 位交易密码。已有密码保持不变。</p></section>`;const name=model.state.profile?.name||'先生';return personalHub()+title('个人中心','管理你的称呼、登录与交易安全。')+`<section class="profile-identity"><span class="recipient-avatar">${esc(name.slice(0,1))}</span><div><h2>${esc(name)}</h2><p>${model.account?'持久账号：'+esc(model.account):'旧浏览器账户 · 尚未迁移'}</p></div></section><div class="profile-settings"><section><h2>个人称呼</h2><form data-form="profile">${field('称呼',`<input name="name" value="${esc(name)}" maxlength="20" required>`)}<button class="btn">保存称呼</button></form></section><section><h2>密码与安全</h2>${mfaSettings()}${model.paymentPasswordLegacy?'<p class="notice">你仍在使用旧版转账密码。展开下方“修改转账密码”，验证旧密码后设置 6 位数字。</p>':''}<p>登录密码用于进入账户；转账密码用于确认交易和敏感操作。修改后会锁定账户，并撤销未执行的确认单。</p>${[['login','登录'],['payment','转账']].map(([kind,label])=>`<details class="password-setting"><summary>修改${label}密码 ${icon('arrow')}</summary><form data-form="changePassword" data-kind="${kind}">${kind==='payment'?paymentField('当前转账密码','currentPassword',model.paymentPasswordLegacy):passwordField('当前登录密码','currentPassword','current-password')}${kind==='payment'?paymentField('新转账密码','newPassword'):passwordField('新登录密码','newPassword')}${kind==='payment'?paymentField('再次输入新密码','confirmPassword'):passwordField('再次输入新密码','confirmPassword')}<p class="small">${kind==='payment'?'新转账密码为 6 位数字，须验证当前旧密码后修改。':'12–128 位，含字母和数字，与旧密码不同。'}</p>${mfaField()}<button class="btn primary">修改${label}密码并锁定</button></form></details>`).join('')}${!model.accountMode?migrationForm():''}${btn('立即锁定账户','lock')}${model.accountMode?btn('退出登录','logout'):''}</section></div><p class="notice">${model.accountMode?'账户数据独立保存；Cookie 到期只需重新登录。忘记密码可用注册时保存的恢复密钥找回，找回后所有设备需重新登录。':'旧浏览器账户仍依赖 Cookie，请使用上方迁移入口保留数据。'}重置账本不会清除密码与账号。</p>`;}

function eventFields(p={}){const local=p.at?new Date(p.at-new Date(p.at).getTimezoneOffset()*60000).toISOString().slice(0,16):'';return `<div class="form-grid">${field('活动名称',`<input name="name" maxlength="40" value="${esc(p.title||'')}" placeholder="例如：周末演唱会" required>`)}${!p.id?field('活动类型','<select name="category">'+['生日','纪念日','节日','演唱会','旅行','自定义'].map(v=>`<option>${v}</option>`).join('')+'</select>'):''}${field('预留预算（元）',`<input name="amount" type="number" min="0" max="1000000" step="0.01" value="${p.amount===undefined?'0':p.amount/100}" required>`,'只需提醒可填 0。')}${field('提醒时间',`<input name="at" type="datetime-local" value="${local}" required>`)}${!p.id?field('分步安排（每行一步）','<textarea name="tasks" maxlength="960" placeholder="核对日期&#10;购票提醒&#10;住宿确认&#10;费用分摊"></textarea>','最多 12 步。完成状态由你手动更新，付款另行确认。'):''}${field('安排与备注',`<textarea name="note" maxlength="240" placeholder="购票时间、活动地点或需要准备的事情">${esc(p.note||'')}</textarea>`)}</div>`;}
function eventEditor(p){if(p.type!=='event'||!['scheduled','ready','paused'].includes(p.status))return '';return `${taskList(p)}<p>${esc(p.category)} · ${esc(p.note||'未填写备注')}</p><details class="event-editor"><summary>编辑${p.status==='paused'?'并恢复提醒':''}</summary><form data-form="eventEdit" data-id="${p.id}">${eventFields(p)}<button class="btn">保存安排</button></form></details>${btn('完成活动并释放剩余预算','completeEvent','',`data-id="${p.id}"`)}${p.amount>0?`<details class="event-editor"><summary>从计划预算付款</summary><form data-form="planPayment" data-plan="${p.id}">${field('商户','<input name="merchant" maxlength="60" required>')}${field('付款金额（元）',`<input name="amount" type="number" min="0.01" max="${p.amount/100}" step="0.01" required>`)}<button class="btn">核对付款</button></form></details>`:''}${p.status==='scheduled'?btn('暂停提醒','pauseEvent','',`data-id="${p.id}"`):''}`;}
function contactPage(){return title('收款人管理','先保存信息，再仔细核对每一笔转账。')+`<p class="notice">保存收款人后，每次转账仍需核对姓名与卡号。</p><details class="plan-composer"><summary>添加银行卡收款人 ${icon('arrow')}</summary><form data-form="contact" class="contact-form"><div class="form-grid">${field('收款人姓名','<input name="name" maxlength="24" required>')}${field('收款银行','<input name="bank" maxlength="40" required placeholder="银行">')}${field('银行卡号','<input name="account" inputmode="numeric" pattern="[0-9]{12,19}" minlength="12" maxlength="19" required>')}</div><button class="btn primary">保存收款人</button></form></details><section class="recipient-directory">${model.contacts.map(c=>`<article><span class="recipient-avatar">${esc(c.name[0])}</span><div><h2>${esc(c.name)}</h2><p>${esc(c.bank||'示例联系人')} · ${esc(c.phone)}</p><small>${esc(c.note)}</small></div>${c.archived?'<span class="tag">已停用</span>':btn('去转账','recipientTransfer','',`data-id="${c.id}"`)}${btn(c.archived?'恢复收款人':'停用收款人','archiveContact32','',`data-id="${c.id}"`)}</article>`).join('')}</section>`;}
const benefitCatalog=[['coffee','咖啡时光','一份咖啡兑换体验','领取后 30 天内有效，每个账户限领一次。'],['travel','轻松出行','城市出行体验券','领取后 30 天内有效；用于展示权益领取与核销流程。'],['reading','阅读时刻','阅读会员体验','领取后 30 天内有效，不开通任何真实服务。']];
function benefitState(b){return !b?'unclaimed':b.status==='used'?'used':b.expires<=model.state.now?'expired':'available';}
function benefitLabel(status){return ({unclaimed:'待领取',available:'可使用',used:'已使用',expired:'已过期'})[status];}
function benefits(){const s=model.state;const items=benefitCatalog.filter(([id,name,desc])=>(benefitCategory==='all'||benefitCategory===id)&&(benefitStatus==='all'||benefitState(s.benefits.find(b=>b.id===id))===benefitStatus)&&(!benefitQuery||(name+desc).includes(benefitQuery)));return `<section class="benefits-intro"><div><span>生活权益</span><h1>发现日常里的小确幸</h1><p>挑选喜欢的体验，领取后到「可使用」查看。</p></div><form data-form="benefitSearch" class="benefit-search"><label class="sr-only" for="benefit-search">搜索权益</label><input id="benefit-search" name="query" type="search" value="${esc(benefitQuery)}" placeholder="搜索咖啡、出行、阅读" maxlength="40"><button class="btn">搜索</button></form></section><nav class="retail-pills" aria-label="权益分类">${[['all','全部权益','gift'],['coffee','咖啡时光','dining'],['travel','城市出行','transport'],['reading','阅读会员','reading']].map(([id,n,i])=>`<button data-action="benefitCategory" data-category="${id}" aria-pressed="${benefitCategory===id}">${icon(i)}${n}</button>`).join('')}</nav><section class="benefit-banner"><img src="/bank/assets/campaign22/life.webp" alt="阳光下的咖啡与旅行静物" width="1200" height="800"><div><span>生活体验精选</span><h2>给自己，一段好时光</h2><p>咖啡、出行、阅读 · 权益，无真实兑换价值</p></div></section><nav class="retail-pills" aria-label="权益状态">${[['all','全部'],['unclaimed','待领取'],['available','可使用'],['used','已使用'],['expired','已过期']].map(([k,n])=>`<button data-action="benefitStatus" data-status="${k}" aria-pressed="${benefitStatus===k}">${n}</button>`).join('')}</nav><div class="benefit-results" aria-live="polite"><p>找到 ${items.length} 项权益${benefitQuery?' · '+esc(benefitQuery):''}</p><div class="coupon-grid">${items.map(([id,name,desc,rule])=>{const b=s.benefits.find(x=>x.id===id),status=benefitState(b);return `<article class="retail-coupon ${id}"><div class="coupon-symbol">${icon(id==='travel'?'transport':id==='coffee'?'dining':'reading')}</div><div class="coupon-copy"><span class="tag">${benefitLabel(status)}</span><h2>${name}</h2><p>${desc}</p><small>${rule}</small>${b?`<small>有效期至 ${stamp(b.expires)}</small>`:''}</div><div class="coupon-actions">${btn('查看详情','benefitDetail','',`data-id="${id}"`)}${status==='unclaimed'?btn('领取权益','benefit','primary',`data-id="${id}" data-op="claim"`):status==='available'?btn('去使用','benefitDetail','primary',`data-id="${id}"`):''}</div></article>`;}).join('')||'<p class="empty">暂无匹配权益，试试其他分类或清空搜索。</p>'}</div></div><section class="panel"><h2>我的权益记录</h2>${s.benefits.map(b=>`<div class="retail-record"><div><strong>${esc(benefitCatalog.find(x=>x[0]===b.id)?.[1]||b.id)}</strong><p>领取 ${stamp(b.claimed)}${b.used?' · 使用 '+stamp(b.used):''}</p></div><span>${benefitLabel(benefitState(b))}</span></div>`).join('')||'<p>还没有领取记录。</p>'}</section>`;}
function showBenefit(id){const item=benefitCatalog.find(x=>x[0]===id);if(!item)return;const b=model.state.benefits.find(x=>x.id===id),state=benefitState(b);$('#confirm-body').innerHTML=`<section class="modal benefit-detail-modal"><div class="benefit-detail-ticket"><div class="result-seal">${icon(id==='coffee'?'dining':id==='travel'?'transport':'reading')}</div><span class="tag">${benefitLabel(state)}</span><h2>${item[1]}</h2><p>${item[2]}</p></div><h3>使用须知</h3><dl class="benefit-rules"><div><dt>使用规则</dt><dd>${item[3]}</dd></div><div><dt>核销方式</dt><dd>在此确认使用，每项权益仅可核销一次。</dd></div>${b?`<div><dt>领取时间</dt><dd>${stamp(b.claimed)}</dd></div><div><dt>有效期至</dt><dd>${stamp(b.expires)}</dd></div>`:''}</dl><p class="modal-disclaimer">领取后请在有效期内使用。</p><div class="form-footer">${btn('返回','close')}${state==='unclaimed'?btn('确认领取','benefit','primary',`data-id="${id}" data-op="claim"`):state==='available'?btn('确认使用','benefit','primary',`data-id="${id}" data-op="use"`):''}</div></section>`;$('#confirm').showModal();}
function gold(){const s=model.state,p=model.products.find(x=>x.id==='gold'),hold=s.holdings.filter(h=>h.product==='gold'),trades=s.goldTrades||[],total=hold.reduce((n,h)=>n+h.amount,0),units=hold.reduce((n,h)=>n+(h.goldUnits||0),0);return `<section class="gold-hero"><div><span>黄金专区</span><h1>看懂黄金<br>再作每一次决定</h1><p>产品、资金与交易记录，清晰呈现。</p>${btn('了解风险与规则','goldTab','','data-tab="rules"')}</div><img src="/bank/assets/campaign22/wealth.webp" width="1200" height="800" alt="金条与玻璃沙漏的原创场景图"></section><nav class="gold-tabs" aria-label="黄金栏目">${[['products','产品'],['holdings','持仓'],['records','交易记录'],['rules','规则与风险']].map(([k,n])=>`<button data-action="goldTab" data-tab="${k}" aria-pressed="${goldTab===k}">${n}</button>`).join('')}</nav>${goldTab==='products'?`<section class="gold-product"><div class="panel-title"><div><span class="tag amber">R4 · 黄金</span><h2>黄金资产体验</h2></div>${icon('gold')}</div><p>按金额买入，逐笔记录克数与扣款卡。</p><div class="gold-price"><div><span>测试成交价（元／克）</span><strong>¥${money(p.priceCents)}</strong><small>与市场参考行情分开展示 · 无手续费 · ¥${money(p.min)}起购</small></div>${btn('买入','goldBuy','primary')}</div><details><summary>产品详情与交易规则</summary><p>${esc(businessCopy(p.description))}</p><p>需有效的 R4 或 R5 风险评估；使用本人借记卡，受卡片余额、状态及限额约束。克数截取至六位小数；赎回以原本金为准，按赎回金额返还原扣款卡。</p></details></section><section class="gold-market"><div id="market-live">${marketView()}</div></section>`:goldTab==='holdings'?`<section class="gold-balance"><span>黄金持有本金（元）</span><strong>¥${money(total)}</strong><p>已记录克数 ${(units/1000000).toFixed(6)} 克${hold.some(h=>h.goldUnits==null)?' · 旧持仓无成交克数，单独按本金展示':''}</p>${btn('继续买入','goldBuy','primary')}</section><section class="panel"><h2>逐笔持仓</h2>${hold.map(h=>`<article class="retail-record"><div><strong>黄金资产体验</strong><p>买入 ${stamp(h.bought)} · 扣款卡尾号 ${esc(s.cards.find(c=>c.id===h.cardId)?.last4||'—')}</p><p>${h.goldUnits==null?'旧版持仓 · 未记录成交克数':(h.goldUnits/1000000).toFixed(6)+' 克 · 测试买入价 ¥'+money(h.priceCents)+'/克'}</p></div><div><strong>¥${money(h.amount)}</strong>${btn('赎回 / 部分赎回','redeem','',`data-id="${h.id}"`)}</div></article>`).join('')||'<p class="empty">暂无黄金持仓。买入确认成功后，会在这里显示。</p>'}</section>`:goldTab==='records'?`<section class="panel"><h2>黄金交易记录</h2><p>每笔已完成交易独立留存，赎回后仍可查询。</p>${trades.map(t=>`<article class="retail-record"><div><strong>${t.side==='buy'?'买入':'赎回'} · 已完成</strong><p>${stamp(t.at)} · 尾号 ${esc(s.cards.find(c=>c.id===t.cardId)?.last4||'—')}</p><small>交易号 ${esc(t.id)}</small><p>${t.goldUnits==null?'旧版持仓，未记录克数':(t.goldUnits/1000000).toFixed(6)+' 克'}${t.side==='sell'?' · 按原本金赎回':''}</p></div><strong>${t.side==='buy'?'-':'+'}¥${money(t.amount)}</strong></article>`).join('')||'<p class="empty">暂无新版黄金交易。历史申购请在账单与回执查询。</p>'}${btn('查看全部交易回执','nav','','data-view="receipts"')}</section>`:`<section class="panel"><h2>交易前，请先了解</h2><p>黄金价格可能波动并产生本金损失。这里是比赛系统，不提供实物交割、真实黄金账户或收益承诺。</p><p>测试成交价为 ¥${money(p.priceCents)}/克。实时行情单独展示，来源延迟或不可用时会说明，均不改变交易价格。</p><p>本版本支持按金额买入、逐笔持仓、部分或全部本金赎回，不含实物金、定投或手续费模型。</p><p>买入前完成十项风险评估。确认时服务端再次检查风险等级、余额与卡片状态；非测试模式保留交易密码与既有多因子验证。</p>${btn('完成风险评估','nav','primary','data-view="invest"')}</section>`}`;}
function showGoldBuy(){const s=model.state,p=model.products.find(x=>x.id==='gold');$('#confirm-body').innerHTML=`<form class="modal" data-form="goldBuy">${flowSteps(0)}<h2>买入黄金</h2><p>测试成交价 ¥${money(p.priceCents)}/克 · 最低 ¥${money(p.min)}。不是实时成交价。</p>${field('扣款借记卡',`<select name="cardId" required>${s.cards.filter(c=>c.kind==='debit').map(c=>`<option value="${c.id}" ${c.id===s.activeCardId?'selected':''}>${esc(c.nickname)} · ${c.last4} · 可用 ¥${money(c.available??c.balance)}</option>`).join('')}</select>`)}${field('买入金额（元）',`<input name="amount" type="number" min="${p.min/100}" max="1000000" step="0.01" required placeholder="输入金额">`)}<p>需有效 R4 或 R5 风险评估。下一步核对克数、扣款卡与金额，确认前不会扣款。</p><p id="modal-error" class="error" role="alert"></p><div class="form-footer">${btn('取消','close')}<button class="btn primary">核对买入</button></div></form>`;$('#confirm').showModal();}

function fx(){return title('外汇与汇率','参考牌价、人民币换算与外币账户。')+`<div id="market-live">${marketView()}</div><section class="panel"><form data-form="fx"><div class="form-grid">${field('人民币金额','<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required>')}${field('目标币种','<select name="currency"><option value="USD">美元 USD</option><option value="EUR">欧元 EUR</option><option value="JPY">日元 JPY</option><option value="GBP">英镑 GBP</option><option value="HKD">港元 HKD</option></select>')}</div><button class="btn primary">按最新参考汇率换算</button></form><p id="fx-result" role="status"></p></section>`;}

function openSearch(){ $('#confirm-body').innerHTML=`<section class="modal"><h2>你想办理什么？</h2><label>搜索功能<input id="bank-search" type="search" placeholder="转账、黄金、卡面、纪念日…" autocomplete="off"></label><div id="search-results">${searchResults('')}</div>${btn('关闭','close')}</section>`;$('#confirm').showModal();$('#bank-search').focus();}
function searchResults(q){const aliases={life:'生活商城支付宝沙箱订单退款门店',gold:'黄金金价买入持仓交易记录',invest:'黄金基金风险问卷评估',plans:'生日纪念日节日演唱会活动旅行',contacts:'添加银行卡联系人收款人',cards:'卡面图片密码挂失限额一类二类借记卡储蓄卡信用卡',benefits:'优惠券会员权益',fx:'外汇美元欧元日元换汇黄金金价汇率',profile:'密码登录转账安全设置称呼个人中心',inbox:'消息待办提醒通知',receipts:'回执凭证预约状态',demo:'场景体验六场景'};const found=navs.filter(([k,n])=>(n+(aliases[k]||'')).includes(q.trim()));return found.map(([k,n])=>`<button class="search-result" data-action="searchNav" data-view="${k}">${icon(k)}${n}${icon('arrow')}</button>`).join('')||'<p>没有匹配功能，试试“转账”或“权益”。</p>';}
function categoryIcon(category,amount){const map={'餐饮':'dining','交通':'transport','出行':'transport','收入':'salary','购物':'shopping','订阅':'subscriptions','居住':'home','生活':'shopping','转账':'transfer','理财':'invest'};return icon(map[category]||(amount>0?'salary':'cards'));}
