setInterval(()=>{if(model&&!model.locked&&model.unlockUntil&&Date.now()>=model.unlockUntil){model={locked:true};render();api({action:'lock'}).catch(()=>{});}},1000);


function taskList(p){return `<div class="plan-task-list">${(p.tasks||[]).map((t,i)=>`<button class="plan-task ${t.done?'done':''}" data-action="taskToggle" data-plan="${p.id}" data-task="${t.id}" aria-pressed="${t.done}"><span>${t.done?'✓':i+1}</span><strong>${esc(t.label)}</strong><small>${t.done?'已完成':'待办理'}</small></button>`).join('')||'<p>这个旧计划没有分步清单，可创建新活动添加。</p>'}<p>需要支付时使用下方预算付款入口，每次均需独立转账密码。AA 分摊可前往转账与收款。</p>${btn('前往转账与 AA 分摊','nav','','data-view="transfer"')}</div>`;}
function inbox(){const list=(model.notifications||[]).filter(n=>inboxFilter!=='unread'||!n.read);return title('消息与待办','把接下来要做的事，放在一起。',btn('全部标为已读','readNotice','','data-id="all"'))+`<div class="tabs"><button data-action="inboxFilter" data-filter="all" class="${inboxFilter==='all'?'selected':''}">全部消息</button><button data-action="inboxFilter" data-filter="unread" class="${inboxFilter==='unread'?'selected':''}">未读 ${(model.notifications||[]).filter(n=>!n.read).length}</button></div><p class="notice">站内提醒依据测试时钟生成。活动到期不自动付款；未接入短信、邮件和浏览器外推送。</p><section class="inbox-list">${list.map(n=>`<article class="notice-item ${n.read?'read':''}"><div><span class="tag">${esc(n.kind)}</span><h2>${esc(businessCopy(n.title))}</h2><p>${esc(n.text)}</p><small>${stamp(n.at)} · ${n.read?'已读':'未读'}</small></div><div>${btn('查看并办理','noticeOpen','',`data-id="${esc(n.id)}" data-view="${n.view}"`)}${!n.read?btn('标为已读','readNotice','',`data-id="${esc(n.id)}"`):''}</div></article>`).join('')||'<p class="empty">当前没有需要处理的消息。</p>'}</section>`;}
function receiptText(id,kind){return businessCopy(rawReceiptText(id,kind));}
function rawReceiptText(id,kind){const s=model.state;if(kind==='transaction'){const t=s.transactions.find(x=>x.id===id);if(!t)return '';return ['个人银行 · 交易回执','测试环境回执，不具有真实银行凭证效力','交易编号：'+t.id,...(t.receiptId?['关联操作回执：'+t.receiptId]:[]),'交易时间：'+stamp(t.at),'交易对象：'+t.merchant,'类型：'+t.category,'状态：'+t.status,'金额：CNY '+money(Math.abs(t.amount)),'方向：'+(t.amount<0?'支出':'收入'),'手续费：CNY '+money(t.fee||0),'渠道：'+(t.channel||'示例账本'),t.recipient?'收款银行：'+(t.recipient.bank||'联系人')+' / 尾号 '+(t.recipient.account?.slice(-4)||t.recipient.phone):'', '备注：'+(t.note||'无')].filter(Boolean).join('\n');}const r=s.receipts.find(x=>x.id===id);if(!r)return '';const plan=s.plans.find(p=>p.id===r.planId)||s.workflows?.find(w=>w.id===r.workflowId||w.confirmationId===r.id);return ['个人银行 · 操作回执','测试环境回执，不具有真实银行凭证效力','回执编号：'+r.id,'操作：'+r.title,'时间：'+stamp(r.at),'状态：'+(plan?status(plan.status):r.status||'已完成'),...(r.lines||[]),...(plan?['执行时间：'+stamp(plan.at),...(plan.steps?.filter(x=>typeof x==='string')||plan.history||[])]:[])].join('\n');}
function downloadReceipt(id,kind){const text=receiptText(id,kind);if(!text){toast('回执不存在');return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='回执-'+id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function receipts(){const s=model.state;return title('交易回执','每次确认都有记录，每笔资金都有去向。')+`<details class="panel"><summary>原始回执与历史入账账本</summary><section><h2>操作与预约回执</h2>${s.receipts.map(r=>{const plan=s.plans.find(p=>p.id===r.planId)||s.workflows?.find(w=>w.id===r.workflowId||w.confirmationId===r.id);return `<details class="receipt-document"><summary><span><strong>${esc(businessCopy(r.title))}</strong><small>${stamp(r.at)}</small></span><span>${plan?recordState(plan.status):r.status||'已完成'}</span></summary><pre>${esc(receiptText(r.id,'operation'))}</pre>${btn('下载回执','receiptDownload','',`data-id="${r.id}" data-kind="operation"`)}${plan&&['scheduled','paused','ready'].includes(plan.status)?btn('取消预约并释放资金','cancelPlan','',`data-id="${plan.id}"`):''}</details>`;}).join('')||'<p>完成一笔操作后，这里会显示确认回执。</p>'}</section><section class="section"><h2>入账交易</h2>${s.transactions.map(t=>`<details class="receipt-document"><summary><span><strong>${esc(t.merchant)}</strong><small>${stamp(t.at)} · ${esc(t.category)}</small></span><b>${t.amount<0?'−':'+'} ¥${money(Math.abs(t.amount))}</b></summary><pre>${esc(receiptText(t.id,'transaction'))}</pre>${btn('下载交易回执','receiptDownload','',`data-id="${t.id}" data-kind="transaction"`)}</details>`).join('')}</section></details>`;}
const demoScenarios=[['transfer','智能转账','transfer','选择收款人或直接填写卡号 → 核对金额 → 输入转账密码 → 查看回执。也可展示预约与 AA 分摊。'],['bills','账单分析','bills','切换月度与年度 → 筛选消费分类 → 展开待核实交易 → 导出账单。'],['invest','适当性与理财','invest','完成 10 项问卷 → 比较风险匹配产品 → 申购 → 查看持仓与赎回限制。'],['cards','银行卡管理','cards','展示多卡与卡面定制 → 调整限额或锁卡 → 验证交易限制。'],['subscriptions','订阅与代扣','subscriptions','查看预计支出 → 开启提醒 → 取消或恢复授权 → 在消息中心检查提醒。'],['birthday','多步骤联动','plans','载入零预算测试计划 → 勾选步骤 → 编辑预算与日期 → 确认付款 → 完成并释放剩余预留。']];
function demo(){return title('场景体验','六个场景，一条可核对的测试路径。')+`<p class="notice">首次载入会切换到独立测试账本，自动生成六场景基础测试数据，个人账本保留。结束测试即可恢复；所有交易仍需本人确认。正式六条要求的最终验收以比赛原文为准。</p><div class="demo-grid">${demoScenarios.map(([id,name,view,steps],i)=>`<article><span class="demo-number">${String(i+1).padStart(2,'0')}</span><h2>${name}</h2><p>${steps}</p>${btn('载入并开始测试','demoSeed','',`data-scenario="${id}" data-view="${view}"`)}</article>`).join('')}</div><section class="section"><h2>测试边界与队友对接</h2><p>已实现：持久账本、独立密码、工具确认、风控校验、回执、消息与活动步骤。</p><p>待对接：真实银行与商户接口、正式身份核验和外部消息投递。本地模型通道支持逐步确认计划，但尚未安装真实模型；未连接时使用规则助手。市场参考报价与测试成交价分开。</p><p>时间测试：在联动计划页展开“测试时钟”，手动推进日期以检查到期状态。账户数据不会因登录会话到期被清除。</p></section>`;}

function render(){if(model.locked){assistantOpen=false;$('#confirm').close();$('#app').innerHTML=lockScreen();return;}const s=model.state;$('#app').innerHTML=`<a class="skip-link" href="#content">跳到主要内容</a><div class="layout" data-page="${view}" ${assistantOpen?'inert':''}><aside class="sidebar"><a class="brand" href="/bank/"><span class="brandmark">银</span><div>个人银行<small>生活与财富</small></div></a><div class="nav-label">我的银行</div><nav class="nav" aria-label="业务导航">${groupedNavigation()}</nav><div class="side-bottom"><button class="side-assistant" data-action="assistant">${icon('spark')}<span>银行助手<small>一句话，查询与办理</small></span></button><button class="security-link" data-action="nav" data-view="security">${icon('shield')} 安全与操作记录</button><a href="/">返回 MANNENZAKURA ${icon('arrow')}</a><div class="side-profile"><span class="avatar">银</span><span>${esc(s.profile?.name||'先生')}<small>个人账户</small></span><span class="status-dot"></span></div></div></aside><div class="shell"><header class="topbar"><div class="crumb">个人银行 <span>/</span> <b>${navs.find(n=>n[0]===view)?.[1]||'安全中心'}</b></div><div class="top-actions"><div class="business-search"><label class="sr-only" for="nav-search">搜索业务</label><input id="nav-search" type="search" placeholder="搜索转账、黄金、卡片…" autocomplete="off" aria-controls="nav-results"><div id="nav-results" hidden></div></div><button class="text-btn" data-action="nav" data-view="inbox">消息 ${model.notifications?.filter(n=>!n.read).length||0}</button><button class="text-btn" data-action="nav" data-view="profile">个人中心</button>${model.testMode?btn('测试模式 · 免密码','exitTest','','role="switch" aria-checked="true" aria-label="测试模式：免密码，点击关闭"'):btn('开启测试模式','enterTest','','role="switch" aria-checked="false"')}${!model.testMode?btn('锁定','lock'):''}<button class="assistant-toggle" data-action="assistant">${icon('spark')} 银行助手</button><button class="icon-button" data-action="nav" data-view="security" aria-label="安全中心">${icon('shield')}</button></div></header><div class="workspace"><main class="main" id="content" tabindex="-1">${s.demoMode?`<div class="demo-session-banner"><strong>独立测试账本</strong><span>操作不会改变你的个人账本</span>${btn('结束测试，返回个人账本','exitDemo')}</div>`:''}${({serviceCenter:()=>'',flights:()=>flights43(model,{esc,money,stamp,btn,field}),stores,utilities,membership,bookings,mall,lifeOrders,paymentLab:()=>title('沙箱接口测试','仅供支付接口联调。'),loans,installments,deposits,overview,accountOverview,life,allServices,transfer,bills,invest,cards,subscriptions,plans,security,benefits,gold,contacts:contactPage,fx,profile,inbox,receipts,tasks,demo}[view]||overview)()}${view==='accountOverview'?balanceSheet34():''}${view==='deposits'?legacyDeposit42():''}${servicePanel37(model,view,{esc,money,stamp,field,btn})}${closurePanel39(model,view,{esc,money,stamp,field,btn,hideBalance})}${commercePanel41(model,view,{esc,money,stamp,btn})}${mobileBankNav()}<footer class="footer"><span>个人银行</span><span>测试环境 · 不涉及真实资金 <a class="home-link" href="/">返回主站</a></span></footer></main></div></div></div>${assistantOpen?`<button class="assistant-scrim" data-action="assistantClose" aria-label="收起金融助手"></button>${assistant()}`:''}`;const log=$('#chat-log');if(log)log.scrollTop=log.scrollHeight;enhanceExperience($('#content'),view);attachBusiness32();adaptAllCardInk();if(['fx','gold'].includes(view))loadMarket();}
function showConfirm(){const p=model.state.pending;if(!p)return;$('#confirm-body').innerHTML=`<form class="modal confirmation-modal" data-form="confirm" aria-labelledby="confirmation-title">${flowSteps(1)}<div class="confirmation-heading"><div class="confirmation-symbol">${icon('shield')}</div><div><span class="tag ${p.strong?'amber':'green'}">${model.testMode?'核对交易信息':p.strong?'交易密码验证':'等待本人确认'}</span><h2 id="confirmation-title">${esc(businessCopy(p.title))}</h2></div></div><div class="confirmation-details">${p.lines.map(x=>`<p>${esc(businessCopy(x))}</p>`).join('')}</div>${p.strong&&!model.testMode?`<section class="verification-area"><h3>验证本次操作</h3>${paymentField('转账密码','pin',model.paymentPasswordLegacy)+mfaField()}</section>`:''}<p class="modal-disclaimer">确认后才执行。确认单 10 分钟有效。</p><p id="modal-error" class="error" role="alert"></p><div class="form-footer">${btn('取消','cancel')}<button class="btn primary" type="submit">确认执行</button></div></form>`;if(!$('#confirm').open)$('#confirm').showModal();}
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));const kind=f.dataset.form;if(kind==='goldBuy')act({action:'prepare',operation:{type:'buy',product:'gold',cardId:d.cardId,amount:Number(d.amount)}});if(kind==='benefitSearch'){benefitQuery=(d.query||'').trim();render();}if(kind==='ownTransfer')act({action:'prepare',operation:{type:'ownTransfer',cardId:d.source,target:d.target,amount:Number(d.amount)}});if(kind==='creditSpend'||kind==='creditRepay')act({action:'prepare',operation:{type:kind,amount:Number(d.amount),merchant:d.merchant,source:d.source}});if(kind==='cardApply')act({action:'prepare',operation:{type:'card',operation:'apply',kind:d.kind,accountClass:d.accountClass}});if(kind==='mfaBegin'||kind==='mfaFinish')act({action:kind,...d});if(kind==='workflow')act({action:'prepare',operation:{type:'workflow',name:d.name,amount:Number(d.amount),at:new Date(d.at).toISOString()}});if(kind==='accountAuth')act({action:f.dataset.mode,...d,migrate:f.dataset.migrate==='true'});if(kind==='planPayment')act({action:'prepare',operation:{type:'planPayment',plan:f.dataset.plan,amount:Number(d.amount),merchant:d.merchant}});if(kind==='unlock')act({action:'unlock',password:d.password});if(kind==='setupPasswords')act({action:'setupPasswords',...d},'密码已设置，请使用登录密码进入');if(kind==='changePassword')act({action:'changePassword',kind:f.dataset.kind,...d},'密码已修改，请重新登录');if(kind==='profile')act({action:'profile',name:d.name},'称呼已更新');if(kind==='contact')act({action:'saveContact',name:d.name,bank:d.bank,account:d.account},'收款人已保存');if(kind==='eventEdit')act({action:'eventUpdate',operation:'edit',id:f.dataset.id,name:d.name,amount:Number(d.amount),at:new Date(d.at).toISOString(),note:d.note},'计划已更新');if(kind==='fx'){const rates=liveMarket?.rates;$('#fx-result').textContent=rates&&!rates.stale?'参考换算 '+(Number(d.amount)*rates.values[d.currency]).toFixed(2)+' '+d.currency+'；报价时间 '+stamp(rates.updatedAt)+'，不执行实际兑换。':'报价不可用或已过期，请刷新后重试。';}const ops={event:()=>({type:'event',name:d.name,category:d.category,amount:Number(d.amount),at:new Date(d.at).toISOString(),note:d.note,tasks:(d.tasks||'').split('\n').map(x=>x.trim()).filter(Boolean)}),bankTransfer:()=>({type:'transfer',recipient:{name:d.name,bank:d.bank,account:d.account},amount:Number(d.amount)}),transfer:()=>({type:'transfer',contact:d.contact,amount:Number(d.amount),at:d.at?new Date(d.at).toISOString():null}),split:()=>({type:'split',amount:Number(d.amount),people:new FormData(f).getAll('people')}),buy:()=>({type:'buy',product:f.dataset.product,amount:Number(d.amount)}),limit:()=>({type:'card',operation:'limit',limit:Number(d.limit)}),birthday:()=>({type:'birthday',contact:d.contact,amount:Number(d.amount),at:new Date(d.at).toISOString()})};if(ops[kind])act({action:'prepare',operation:ops[kind]()});if(kind==='cardDesign')act({action:'customizeCard',id:model.state.activeCardId,nickname:d.nickname,theme:d.theme,pattern:d.pattern,artwork:artDraft,textMode:d.textMode,textColor:d.textColor},'卡面已保存');if(kind==='risk')act({action:'risk',answers:Array.from({length:10},(_,i)=>Number(d['q'+i]))},'风险评估已保存');if(kind==='chat')act({action:'chat',text:d.text});if(kind==='confirm')act({action:'confirm',id:model.state.pending.id,pin:d.pin,otp:d.otp},'操作已完成，账本已更新');if(kind==='reset')act({action:'reset',confirm:d.confirm==='重置账户'?'重置'+'模拟'+'账户':d.confirm},'已建立全新的账本');});
document.addEventListener('keydown',e=>{if(assistantOpen&&!$('#confirm').open){if(e.key==='Escape'){assistantOpen=false;render();$('.assistant-toggle').focus();return;}if(e.key==='Tab'){const controls=[...document.querySelectorAll('.assistant button,.assistant textarea')].filter(x=>!x.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form.requestSubmit();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;const d=b.dataset,s=model.state;switch(d.action){case'recipientTransfer':selectedRecipient=d.id;transferTab='transfer';navigateBank('transfer');break;case'resultFinance34':$('#confirm').close();navigateBank(d.view);break;case'resultRecords':$('#confirm').close();navigateBank('receipts');break;case'quoteRange':quoteRange=d.range;if($('#market-live'))$('#market-live').innerHTML=marketView();break;case'goldTab':goldTab=d.tab;render();break;case'benefitCategory':benefitCategory=d.category;render();break;case'benefitStatus':benefitStatus=d.status;render();break;case'benefitDetail':showBenefit(d.id);break;case'goldBuy':showGoldBuy();break;case'cardCatalog':document.querySelector('#card-catalog').open=true;document.querySelector('#card-catalog').scrollIntoView({behavior:'smooth'});break;case'marketRefresh':loadMarket(true);break;case'workflowControl':act({action:'workflowControl',id:d.id,operation:d.op});break;case'workflowFault':act({action:'workflowFault',id:d.id,step:d.step});break;case'runTasks':act({action:'runTasks'});break;case'subDetect':act({action:'prepare',operation:{type:'subscriptionDetect',id:d.id}});break;case'splitCollect':act({action:'prepare',operation:{type:'splitCollect',split:d.split,contact:d.contact}});break;case'enterTest':act({action:'enterTest'}).then(()=>navigateBank('overview'));break;case'exitTest':authMode='login';act({action:'exitTest'});break;case'passwordMode':authMode='login';render();break;case'authMode':authMode=d.mode;render();break;case'recoverySaved':delete model.recoveryKey;authMode='login';render();break;case'logout':act({action:'logout'});break;case'inboxFilter':inboxFilter=d.filter;render();break;case'readNotice':act({action:'readNotification',id:d.id});break;case'noticeOpen':act({action:'readNotification',id:d.id}).then(()=>navigateBank(d.view));break;case'taskToggle':act({action:'taskToggle',plan:d.plan,task:d.task});break;case'completeEvent':act({action:'completeEvent',id:d.id},'活动已完成，剩余预留资金已释放');break;case'exitDemo':act({action:'exitDemo'},'已回到个人账本').then(()=>navigateBank('overview'));break;case'demoSeed':act({action:'demoSeed',scenario:d.scenario},'已进入独立测试账本').then(()=>navigateBank(d.view));break;case'receiptDownload':downloadReceipt(d.id,d.kind);break;case'lock':act({action:'lock'});break;case'search':openSearch();break;case'benefit':act({action:'benefit',id:d.id,operation:d.op},'权益已更新');break;case'pauseEvent':act({action:'eventUpdate',id:d.id,operation:'pause'},'提醒已暂停，预算保留');break;case'selectCard':switchWallet(d.id);break;case'cycleCard':cycleWallet(Number(d.direction));break;case'resetDesign':render();break;case'assistant':assistantOpen=true;render();$('#chat-input').focus();break;case'assistantClose':assistantOpen=false;render();$('.assistant-toggle').focus();break;case'privacy':act({action:'lock'});break;case'wealthCategory':wealthCategory=d.category;render();break;case'nav':navigateBank(d.view);break;case'transferTab':transferTab=d.tab;render();break;case'period':period=d.period;billFilter='all';render();break;case'subscriptionFilter':subscriptionFilter=d.filter;render();document.querySelector('.subscription-filters [aria-pressed=true]')?.focus({preventScroll:true});break;case'billFilter':billFilter=d.filter;{const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});document.querySelector('.statement-filters [aria-pressed=true]')?.focus({preventScroll:true});}break;case'suggest':act({action:'chat',text:d.text});break;case'pending':showConfirm();break;case'cancel':act({action:'cancel'});break;case'card':act({action:'prepare',operation:{type:'card',operation:d.op}});break;case'online':act({action:'prepare',operation:{type:'card',operation:'online',enabled:!s.card.online}});break;case'redeem':showRedeem32(d.id);break;case'sub':act({action:'prepare',operation:{type:'subscription',id:d.id,operation:d.op}});break;case'cancelPlan':act({action:'prepare',operation:{type:'cancelPlan',id:d.id}});break;case'clock':act({action:'prepare',operation:{type:'clock',days:Number(d.days)}});break;case'export':{const tx=calcReport().tx;const csv='\ufeff日期,商户,分类,金额,备注\n'+tx.map(t=>[stamp(t.at),t.merchant,t.category,(t.amount/100).toFixed(2),t.note].map(x=>'"'+businessCopy(x).replace(/"/g,'""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='银行助手-账单.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('账单已导出');break;}case'reset':$('#confirm-body').innerHTML=`<form class="modal" data-form="reset"><h2>重置账户</h2><p class="small muted">清除当前沙箱的操作记录与计划，恢复初始测试数据。</p>${field('输入“重置账户”确认','<input name="confirm" required placeholder="重置账户">')}<div class="form-footer">${btn('返回','close')}<button class="btn danger">重置</button></div></form>`;$('#confirm').showModal();break;case'close':$('#confirm').close();break;}});
