// Material response is decorative only; it never changes a transaction or account state.
const cardMotion=matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)');
document.addEventListener('pointermove',e=>{if(!cardMotion.matches||e.target.closest('#card-preview'))return;const card=e.target.closest('.payment-card');if(!card)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;card.style.setProperty('--rx',`${(0.5-y)*7}deg`);card.style.setProperty('--ry',`${(x-0.5)*9}deg`);card.style.setProperty('--lx',`${x*100}%`);card.style.setProperty('--ly',`${y*100}%`);});
document.addEventListener('pointerout',e=>{const card=e.target.closest('.payment-card');if(card&&!card.contains(e.relatedTarget)){card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg');card.style.setProperty('--lx','30%');card.style.setProperty('--ly','10%');}});

document.addEventListener('change',e=>{if(e.target.name==='activeCard')act({action:'selectCard',id:e.target.value},'已切换当前卡片');});
document.addEventListener('input',e=>{if(!e.target.closest('[data-form="cardDesign"]'))return;if(e.target.name==='textColor')e.target.form.querySelector('[name=textMode][value=manual]').checked=true;if(e.target.dataset.crop&&artDraft)artDraft[e.target.dataset.crop]=Number(e.target.value);updateArtworkPreview();});

const reducedMotion=matchMedia('(prefers-reduced-motion:reduce)');
let viewTransition=null,swipeStart=null,swipeBlockUntil=0;
function navigateBank(next){if(next===view)return;recordQuery32='';recordStatus32='all';recordCard32='all';viewTransition?.skipTransition();view=next;const url=new URL(location.href);url.searchParams.set('page',next);url.searchParams.delete('commerce');history.pushState({page:next},'',url);render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});}
async function switchWallet(id){if(id===model.state.activeCardId||busy)return;const old=$('.wallet-card-frame');if(old&&!reducedMotion.matches){old.classList.add('wallet-leaving');}await act({action:'selectCard',id},'已切换当前银行卡');const current=$('.wallet-card-frame');if(current&&!reducedMotion.matches)current.classList.add('wallet-arriving');}
function cycleWallet(direction){const s=model.state;if(s.cards.length<2||busy)return;const i=s.cards.findIndex(c=>c.id===s.activeCardId);switchWallet(s.cards[(i+direction+s.cards.length)%s.cards.length].id);}
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-wallet-swipe]')&&e.pointerType!=='mouse')swipeStart={x:e.clientX,y:e.clientY,id:e.pointerId};});
document.addEventListener('pointerup',e=>{if(!swipeStart||swipeStart.id!==e.pointerId)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.4){swipeBlockUntil=Date.now()+450;cycleWallet(dx<0?1:-1);}});
document.addEventListener('pointercancel',()=>{swipeStart=null;});
document.addEventListener('click',e=>{if(Date.now()<swipeBlockUntil&&e.target.closest('[data-wallet-swipe]')){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('pointerdown',e=>{const b=e.target.closest('.btn,.personal-services>button');if(!b||b.disabled||reducedMotion.matches)return;const r=b.getBoundingClientRect(),pulse=document.createElement('span');pulse.className='press-pulse';pulse.style.left=(e.clientX-r.left)+'px';pulse.style.top=(e.clientY-r.top)+'px';pulse.setAttribute('aria-hidden','true');b.append(pulse);pulse.addEventListener('animationend',()=>pulse.remove(),{once:true});});
function mfaField(){return model.mfaRequired?field('身份验证器动态码','<input name="otp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required>',model.mfaEnabled?'每次使用一个新的动态码。':'请先取消操作，在个人中心绑定身份验证器。'):'';}
function mfaSettings(){if(model.mfaEnabled)return '<p class="notice">身份验证器已绑定。敏感操作需交易密码和动态码。</p>';return `<details class="password-setting" ${model.enrollmentSecret?'open':''}><summary>绑定身份验证器</summary><p>使用支持 TOTP 的身份验证器，手动添加密钥。无需短信服务。</p>${model.enrollmentSecret?`<p>密钥仅用于你的身份验证器，请勿分享：</p><code>${esc(model.enrollmentSecret)}</code><form data-form="mfaFinish">${field('验证动态码','<input name="otp" pattern="[0-9]{6}" inputmode="numeric" maxlength="6" required>')}<button class="btn primary">确认绑定</button></form>`:`<form data-form="mfaBegin">${passwordField('验证登录密码','password','current-password')}<button class="btn">生成绑定密钥</button></form>`}</details>`;}
function subscriptionDiscovery(){return `<section class="panel"><h2>从账单发现周期扣费</h2><p>至少三期、间隔 25–35 天、金额波动不超过 10%。候选不等于已授权。</p>${(model.subscriptionCandidates||[]).map(x=>`<article><h3>${esc(x.name)} · ¥${money(x.amount)}</h3><p>依据交易：${x.evidence.map(esc).join('、')}</p>${btn('核对并记录提醒','subDetect','',`data-id="${esc(x.id)}"`)}</article>`).join('')||'<p>暂无满足条件的新订阅。</p>'}</section>`;}
function investmentComparison(){return `<details class="panel"><summary>适配产品比较与推荐依据</summary><p>按已完成的风险评估筛选，不预测收益。</p><div style="overflow:auto"><table><thead><tr><th>产品</th><th>风险</th><th>持有天数</th><th>最低金额</th><th>依据</th></tr></thead><tbody>${(model.recommendations||[]).filter(p=>!['gold','deposit'].includes(p.id)).map(p=>`<tr><td>${esc(businessCopy(p.name))}</td><td>R${p.risk}</td><td>${p.days}</td><td>¥${money(p.min)}</td><td>${esc(p.reason)}</td></tr>`).join('')}</tbody></table></div>${model.recommendations?.length?'':'<p>请先完成下方风险评估。</p>'}</details>`;}
function tasks(){return title('自动任务中心','先确认预算，再让计划按步骤执行。')+`<section class="panel"><h2>鲜花与蛋糕联动预订</h2><p>生日、纪念日均可使用。提前两天启动，鲜花占预算 60%、蛋糕占 40%。操作完成后可查看订单号和执行记录。</p><form data-form="workflow"><div class="form-grid">${field('活动名称','<input name="name" maxlength="40" required placeholder="爱人的生日">')}${field('活动时间','<input name="at" type="datetime-local" required>')}${field('总预算（元）','<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required>')}</div><button class="btn primary">预览计划与授权范围</button></form></section><div class="panel"><p>${model.testMode||model.state.demoMode?'测试账本使用测试时钟，可推进一天检验到期执行。':'后台每 15 分钟处理到期计划，访问账户时也会检查。'}已完成订单不通过取消任务自动退款。</p>${btn('检查到期任务','runTasks')}${model.testMode||model.state.demoMode?btn('推进测试时钟一天','clock','','data-days=1'):''}</div>${(model.state.workflows||[]).map(w=>`<section class="panel"><h2>${esc(w.name)}</h2><p>${esc(status(w.status))} · 剩余预留 ¥${money(w.remaining)} · 启动 ${stamp(w.at)}</p><ol>${w.steps.map(step=>`<li><strong>${esc(step.merchant)}</strong> ¥${money(step.amount)} · ${esc(status(step.status))} · 尝试 ${step.attempts} 次${step.orderId?`<p>订单 ${esc(step.orderId)}</p>`:''}</li>`).join('')}</ol><div class="form-footer">${!['completed','cancelled'].includes(w.status)?`${btn('暂停','workflowControl','',`data-id="${w.id}" data-op="pause"`)}${btn('恢复 / 人工重试','workflowControl','',`data-id="${w.id}" data-op="resume"`)}${btn('取消剩余步骤','workflowControl','',`data-id="${w.id}" data-op="cancel"`)}`:''}${model.testMode?`${btn('蛋糕商户故障','workflowFault','',`data-id="${w.id}" data-step="cake"`)}${btn('恢复测试商户','workflowFault','',`data-id="${w.id}" data-step=""`)}`:''}</div><details><summary>执行记录</summary><ol>${w.history.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details></section>`).join('')||'<p class="empty">尚无自动计划，也可以向银行助手描述需求。</p>'}`;}
function wallClock(){return new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})+' 北京时间';}
setInterval(()=>document.querySelectorAll('[data-wallclock]').forEach(x=>x.textContent=wallClock()),1000);
function groupedNavigation(){const groups=[['账户与卡片',['accountOverview','cards','installments','loans','contacts','profile','security']],['支付与账单',['transfer','bills','subscriptions','receipts']],['财富管理',['invest','deposits','gold','fx']],['生活服务',['life','flights','stores','utilities','membership','bookings','mall','lifeOrders','plans','tasks','benefits','inbox','demo']]];return `<button data-action="nav" data-view="overview" class="${view==='overview'?'active':''}">首页</button>`+groups.map(([name,items])=>`<details class="nav-group"><summary class="${items.includes(view)?'active':''}">${name}<span aria-hidden="true">⌄</span></summary><div class="nav-submenu">${items.map(k=>`<button data-action="nav" data-view="${k}" ${view===k?'aria-current="page"':''}>${icon(k)}${navs.find(n=>n[0]===k)?.[1]||'安全中心'}</button>`).join('')}</div></details>`).join('');}
document.addEventListener('pointerover',e=>{const d=e.target.closest('.nav-group');if(d&&matchMedia('(hover:hover)').matches)d.open=true;});
document.addEventListener('pointerout',e=>{const d=e.target.closest('.nav-group');if(d&&!d.contains(e.relatedTarget)&&!d.contains(document.activeElement))d.open=false;});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.nav-group')&&e.target.open)document.querySelectorAll('.nav-group').forEach(d=>{if(d!==e.target)d.open=false;});},true);
document.addEventListener('input',e=>{if(e.target.id==='nav-search'){const box=$('#nav-results');box.hidden=!e.target.value.trim();box.innerHTML=searchResults(e.target.value);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.nav-group[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus();});const results=$('#nav-results');if(results)results.hidden=true;}if(e.target.id==='nav-search'&&e.key==='ArrowDown'){$('#nav-results button')?.focus();e.preventDefault();}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))document.querySelectorAll('.nav-group').forEach(d=>d.open=false);if(!e.target.closest('.business-search')&&$('#nav-results'))$('#nav-results').hidden=true;});
function marketView(){if(view==='fx')return fxMarket42(liveMarket,{money,stamp,btn});const m=liveMarket,r=m?.rates,g=m?.gold,h=m?.history;const sign=v=>(v>0?'+':'')+v.toFixed(2);return `<section class="quote-board"><header class="quote-header"><div><span>贵金属行情</span><h2>国际黄金 <small>XAU</small></h2></div>${btn(marketBusy?'更新中…':'刷新行情','marketRefresh')}</header><div class="quote-main"><div><span>人民币参考克价</span><strong>${g?.cnyPerGram?'¥ '+g.cnyPerGram.toFixed(2):'—'}<small> / 克</small></strong><p>${g?`${g.stale?'行情已延迟':'最新可用报价'} · ${stamp(g.updatedAt)}`:'暂未取得报价，请稍后刷新'}</p></div><div class="quote-secondary"><span>国际现货参考价</span><b>${g?'$ '+g.usdPerOunce.toFixed(2):'—'}</b><small>美元／金衡盎司</small></div></div><div class="quote-performance">${[['day','日收盘涨跌'],['month','近一个月'],['quarter','近三个月'],['year','同比（近一年）']].map(([k,n])=>{const c=h?.changes[k];return `<div><span>${n}</span><strong class="${c?c.percent>0?'quote-up':c.percent<0?'quote-down':'':''}">${c?sign(c.percent)+'%':'—'}</strong><small>${c?'基准 '+c.baseDate:'历史数据不足'}</small></div>`;}).join('')}</div><p class="quote-caption">${h?`涨跌截至 ${h.asOf}${h.stale?' · 历史数据已延迟':''}，按美元日收盘价计算；休市日采用此前最近可用收盘价。`:'历史行情暂不可用，涨跌幅与曲线不作估算。'}</p><div class="quote-chart-heading"><h3>黄金历史走势</h3><nav aria-label="行情周期">${[['month','近1月'],['quarter','近3月'],['year','近1年']].map(([k,n])=>`<button data-action="quoteRange" data-range="${k}" aria-pressed="${quoteRange===k}">${n}</button>`).join('')}</nav></div>${goldChart(h)}<details class="quote-sources"><summary>数据来源与计算口径</summary><p>实时参考价：<a href="https://gold-api.com" target="_blank" rel="noopener">Gold API</a>。历史日收盘价：<a href="https://xaus.com/api/" target="_blank" rel="noopener">XAUS</a>${h?.updatedAt?'，源更新时间 '+stamp(h.updatedAt):''}。两者来源不同，不将实时价与历史价混算涨跌幅。</p><p>人民币克价用美元现货价、人民币日参考汇率和每金衡盎司 31.1034768 克换算。汇率日期：${r?stamp(r.updatedAt):'暂无'}。图表与涨跌幅均为美元／金衡盎司口径，不代表人民币收益率或银行成交价。</p><p>日收盘涨跌对比上一可用收盘价；月、季度、同比对比截止日期前 1、3、12 个日历月的可用收盘价。缺失超过 7 日不计算。实时行情每分钟检查，历史行情最多缓存六小时。此行情不改变交易的测试成交价。</p></details></section>`;}
function goldChart(h){if(!h?.points?.length)return '<div class="quote-empty">暂无历史曲线，恢复数据后自动展示。</div>';const end=Date.parse(h.asOf),days=quoteRange==='month'?31:quoteRange==='quarter'?93:366,points=h.points.filter(p=>end-Date.parse(p.date)<=days*86400000);if(points.length<2)return '<div class="quote-empty">该周期数据不足。</div>';const min=Math.min(...points.map(p=>p.close)),max=Math.max(...points.map(p=>p.close)),spread=max-min||1,start=Date.parse(points[0].date),span=end-start||1;const coords=points.map(p=>[55+(Date.parse(p.date)-start)/span*690,25+(max-p.close)/spread*175]);const line=coords.map(([x,y])=>x.toFixed(2)+','+y.toFixed(2)).join(' ');return `<div class="quote-chart"><svg viewBox="0 0 800 235" role="img" aria-label="美元黄金日收盘走势，从 ${points[0].date} 到 ${h.asOf}，最低 ${min.toFixed(2)}，最高 ${max.toFixed(2)} 美元每金衡盎司"><path d="M55 25H745M55 112H745M55 200H745" stroke="#e6e7df" fill="none"/><polygon points="55,200 ${line} 745,200" fill="#c99b5118"/><polyline points="${line}" fill="none" stroke="#aa792a" stroke-width="2.5" stroke-linejoin="round"/><text x="52" y="17">${max.toFixed(2)}</text><text x="52" y="219">${min.toFixed(2)}</text></svg><div class="quote-chart-labels"><span>${points[0].date}</span><span>美元／金衡盎司</span><span>${h.asOf}</span></div></div><details class="quote-table"><summary>查看该周期 ${points.length} 条日收盘数据</summary><div><table><thead><tr><th>日期</th><th>收盘价（美元／金衡盎司）</th></tr></thead><tbody>${points.slice().reverse().map(p=>`<tr><td>${p.date}</td><td>${p.close.toFixed(2)}</td></tr>`).join('')}</tbody></table></div></details>`;}

async function loadMarket(force=false){if(marketBusy||(!force&&Date.now()-marketFetched<60000))return;marketBusy=true;try{liveMarket=await api({action:'marketQuotes'});marketFetched=Date.now();}catch{liveMarket=null;}finally{marketBusy=false;if($('#market-live'))$('#market-live').innerHTML=marketView();}}
setInterval(()=>{if(model&&!model.locked&&['fx','gold'].includes(view)&&!document.hidden)loadMarket();},60000);
function cardType(c){return c.kind==='credit'?'信用卡':`借记卡 · ${c.accountClass==='II'?'Ⅱ':'Ⅰ'}类账户`;}
function cardCatalog(){const c=model.state.card;return `<section class="panel"><h2>${cardType(c)}</h2><p>${c.kind==='credit'?`授信 ¥${money(c.creditLimit||0)} · 当前欠款 ¥${money(c.outstanding||0)}。支持消费、月度账单与还款；授信不计入现金资产。`:'储蓄卡通常指借记卡，使用存款资金；Ⅰ类、Ⅱ类是个人银行结算账户分类。每张借记卡独立余额账本，Ⅱ类按卡校验收支累计限额。'}</p><details id="card-catalog"><summary>选择卡片类型，添加卡</summary><form data-form="cardApply"><div class="form-grid">${field('卡片类型','<select name="kind"><option value="debit">借记卡（储蓄卡）</option><option value="credit">信用卡</option></select>')}${field('借记账户类别','<select name="accountClass"><option value="II">Ⅱ类账户</option><option value="I">Ⅰ类账户（同一银行仅一个）</option></select>','信用卡不使用此分类。')}</div><button class="btn primary">查看申请确认单</button></form></details></section>`;}

function cardBusiness(s,c){
 if(c.kind!=='credit'){const q=c.classQuota||{},ii=c.accountClass==='II';return `<section class="credit-hub"><div class="panel-title"><h2>${ii?'Ⅱ类账户 · 日常限额支付':'Ⅰ类账户 · 综合资金账户'}</h2><span class="tag">${cardType(c)}</span></div><div class="credit-metrics"><div><span>本卡余额</span><strong>¥${money(c.balance||0)}</strong></div><div><span>本卡预留</span><strong>¥${money(c.reserved||0)}</strong></div><div><span>本卡可用</span><strong>¥${money(c.available||0)}</strong></div></div>${ownTransferForm(s)}<p>${ii?'非绑定收支分别按日 ¥10,000、按年 ¥200,000 累计校验；提高单笔限额也不能绕过累计限额。':'不受Ⅱ类账户累计额度约束；仍校验单笔限额、卡片状态及可用余额。'}</p>${ii?`<div class="credit-metrics"><div><span>今日已支出 / 10,000</span><strong>¥${money(q.dailyOut||0)}</strong></div><div><span>本年已支出 / 200,000</span><strong>¥${money(q.yearlyOut||0)}</strong></div><div><span>今日已转入 / 10,000</span><strong>¥${money(q.dailyIn||0)}</strong></div><div><span>本年已转入 / 200,000</span><strong>¥${money(q.yearlyIn||0)}</strong></div></div>`:''}<p class="design-hint">规则：按北京时间自然日及自然年统计。每张卡独立余额及限额；本人卡间转账尚无绑定豁免，分别计入转出卡和转入卡累计额度；本版无现金存取，理财申购赎回不计此限额，信用卡还款计入支出。</p></section>`;}
 const billed=(c.statements||[]).reduce((n,b)=>n+b.remaining,0),available=c.creditLimit-c.outstanding,ordinary=c.creditEntries.filter(e=>!e.installmentId).reduce((n,e)=>n+e.remaining,0);
 return `<section class="credit-hub"><div class="panel-title"><h2>信用卡生活</h2><span class="tag">尾号 ${c.last4}</span></div><div class="credit-metrics"><div><span>可用额度</span><strong>¥${money(available)}</strong></div><div><span>总欠款</span><strong>¥${money(c.outstanding)}</strong></div><div><span>已出账待还</span><strong>¥${money(billed)}</strong></div><div><span>非分期未出账</span><strong>¥${money(ordinary-billed)}</strong></div></div><progress aria-label="授信使用比例" max="${c.creditLimit}" value="${c.outstanding}"></progress><p>总授信 ¥${money(c.creditLimit)} · 下次出账 ${stamp(c.nextStatementAt)}</p><div class="credit-actions"><form data-form="creditSpend"><h3>消费</h3>${field('商户名称','<input name="merchant" maxlength="60" required placeholder="例如：城市书店">')}${field('消费金额（元）','<input name="amount" type="number" min="0.01" step="0.01" required>')}<button class="btn primary">核对消费</button></form><form data-form="creditRepay"><h3>偿还非分期欠款</h3>${field('还款借记卡',`<select name="source" required>${s.cards.filter(x=>x.kind==='debit').map(x=>`<option value="${x.id}">${esc(x.nickname)} · ${cardType(x)} · ${x.last4}</option>`).join('')}</select>`)}${field('还款金额（元）',`<input name="amount" type="number" min="0.01" max="${ordinary/100}" step="0.01" value="${ordinary?ordinary/100:''}" required>`)}<button class="btn primary" ${ordinary?'':'disabled'}>核对还款</button></form></div><section class="panel"><h3>消费分期</h3><p>查看总费用、分期明细、逐期还款与提前结清；分期本金仍占用额度。</p>${btn('管理分期','nav','primary','data-view="installments"')}</section><h3>月度账单</h3>${model.testMode||s.demoMode?btn('推进至下次出账日','clock','',`data-days="${Math.max(1,Math.ceil((c.nextStatementAt-s.now)/86400000))}"`):''}${(c.statements||[]).map(b=>`<div class="credit-row"><div><strong>${stamp(b.at)} 出账</strong><p>到期 ${stamp(b.dueAt)} · ${b.remaining===0?(b.converted?'已还清或转分期':'已还清'):b.dueAt<s.now?'已逾期，请还款':'待还款'}</p></div><div>账单 ¥${money(b.amount)}<br>剩余 ¥${money(b.remaining)}</div><details class="credit-statement32"><summary>查看本期消费及还款分配</summary>${c.creditEntries.filter(e=>e.statementId===b.id).map(e=>`<article><strong>${esc(e.merchant)}</strong><p>${stamp(e.at)} · 消费 ¥${money(e.amount)} · 已偿还 ¥${money(e.amount-e.remaining)} · 待还 ¥${money(e.remaining)}</p></article>`).join('')||'<p>本期无消费明细。</p>'}</details></div>`).join('')||'<p>暂无已出账账单。消费后可推进测试时间至出账日，验证自动出账。</p>'}<details><summary>消费明细（${(c.creditEntries||[]).length} 笔）</summary>${(c.creditEntries||[]).slice().reverse().map(e=>`<div class="credit-row"><div><strong>${esc(e.merchant)}</strong><p>${stamp(e.at)} · ${e.installmentId?'已转分期':e.statementId?'已出账':'未出账'}</p></div><div>¥${money(e.amount)}<br>待还 ¥${money(e.remaining)}</div></div>`).join('')||'<p>尚无消费，试着完成第一笔付款。</p>'}</details><p class="design-hint">每月 1 日自动出账，20 天后到期；还款优先抵扣最早消费并恢复额度，支持部分或全部还款。逾期会暂停消费。非分期余额暂不计息，不提供最低还款或取现；消费分期单独计费和还款。</p></section>`;
}

function ownTransferForm(s){const cards=s.cards.filter(c=>c.kind==='debit');return `<details class="plan-composer"><summary>本人卡间转账 <span>在自己的借记卡之间调配资金</span></summary>${cards.length<2?'<p>请先在卡片管理添加第二张借记卡，新卡余额为零。</p>':`<form data-form="ownTransfer"><div class="form-grid">${field('转出借记卡',`<select name="source">${cards.map(c=>`<option value="${c.id}" ${c.id===s.activeCardId?'selected':''}>${esc(c.nickname)} · ${c.last4} · 可用 ¥${money(c.available||0)}</option>`).join('')}</select>`)}${field('转入借记卡',`<select name="target">${cards.map((c,i)=>`<option value="${c.id}" ${c.id!==s.activeCardId&&c===cards.find(x=>x.id!==s.activeCardId)?'selected':''}>${esc(c.nickname)} · ${c.last4} · 余额 ¥${money(c.balance||0)}</option>`).join('')}</select>`)}${field('卡间转账金额（元）','<input name="amount" type="number" min="0.01" step="0.01" required>')}</div><p>转账不增加收入或支出。Ⅱ类卡转入与转出分别校验累计限额，不会借用另一张卡的额度。</p><button class="btn primary">核对卡间转账</button></form>`}</details>`;}

function serviceGrid(items,cls=''){return `<div class="bank-service-grid ${cls}">${items.map(([key,label,ico])=>`<button data-action="nav" data-view="${key}"><span class="bank-service-icon">${icon(ico||key)}</span><strong>${label}</strong></button>`).join('')}</div>`;}
function overview(){const s=model.state,notice=model.notifications?.find(n=>!n.read);return `<section class="bank-home-welcome"><div><p>个人银行 · 生活与财富</p><h1>${esc(s.profile?.name||'先生')}，欢迎回来</h1><time data-wallclock>${wallClock()}</time></div><button class="bank-helper" data-action="assistant">${icon('spark')} 银行助手</button></section><section class="bank-home-stage">${serviceGrid([['transfer','转账汇款'],['accountOverview','账户总览','overview'],['cards','我的银行卡'],['bills','收支明细']],'bank-primary-services')}<div class="bank-feature"><div><span class="bank-feature-kicker">把重要的日子，提前安排好</span><h2>生活有计划<br>每一份心意，都有准备</h2><p>纪念日、旅行、演唱会。创建计划，留出预算，逐步完成。</p>${btn('创建我的计划','nav','primary','data-view="plans"')}</div><figure class="campaign-art"><img src="/bank/assets/campaign22/home.webp" width="1200" height="800" alt="" fetchpriority="high"></figure></div></section><section class="bank-service-panel">${serviceGrid([['cards','信用卡','cards'],['invest','理财产品','invest'],['gold','黄金专区','gold'],['benefits','我的权益','gift'],['allServices','全部服务','overview'],['subscriptions','订阅代扣','subscriptions'],['plans','活动计划','plans'],['contacts','收款人','people'],['receipts','交易回执','bills'],['life','生活服务','dining']])}</section><button class="bank-notice" data-action="nav" data-view="inbox"><b>通知</b><span>${notice?esc(businessCopy(notice.title)):'暂无待办，查看你的消息与交易回执'}</span>${icon('arrow')}</button><div class="bank-home-columns"><section class="bank-editorial"><div class="panel-title"><h2>财富，从了解开始</h2>${btn('进入财富','nav','','data-view="invest"')}</div><p>看清持有期限与风险，再决定资金的安排。</p><div class="bank-product-previews">${model.products.filter(p=>['cash','steady','gold'].includes(p.id)).map(p=>`<button data-action="nav" data-view="${p.id==='gold'?'gold':'invest'}"><span>R${p.risk} · ${p.days?p.days+' 天持有':'灵活期限'}</span><h3>${esc(businessCopy(p.name))}</h3><strong>¥${money(p.min)}<small> 起购</small></strong><p>产品 · 查看详情与风险</p></button>`).join('')}</div></section><section class="bank-life-teaser campaign-teaser"><figure class="campaign-art"><img src="/bank/assets/campaign22/life.webp" width="1200" height="800" alt="" loading="lazy"></figure><span>生活权益</span><h2>一杯咖啡，一段旅程<br>让日常多一点期待</h2><p>查看、领取、使用你的权益，记录每一次小确幸。</p>${btn('查看我的权益','nav','primary','data-view="benefits"')}</section></div><section class="bank-guide"><h2>第一次使用？从这里开始</h2><details><summary>银行卡与转账怎么使用？</summary><p>在卡片管理添加借记卡，使用本人卡间转账分配余额。每张卡独立记账，Ⅱ类账户单独计算累计限额。</p>${btn('打开卡片管理','nav','','data-view="cards"')}</details><details><summary>如何体验信用卡消费与还款？</summary><p>添加并选中信用卡后，在卡包填写商户和金额。消费占用额度，还款从所选借记卡扣款并恢复授信。</p>${btn('去卡包体验','nav','','data-view="cards"')}</details><details><summary>如何让生日或纪念日自动执行？</summary><p>自动任务中心可预留预算并安排鲜花与蛋糕预订。测试模式使用测试时钟，失败任务可重试或取消。</p>${btn('查看自动任务','nav','','data-view="tasks"')}</details></section>`;}
function allServices(){return title('全部服务','找到你要办理的业务。也可以使用顶部搜索框。')+`<section class="bank-service-panel">${serviceGrid(navs.filter(([k])=>!['overview','allServices','demo'].includes(k)).map(([k,n])=>[k,n]))}</section>`;}
function legacyLife(){const s=model.state;return `<section class="bank-life-hero campaign-hero"><div class="campaign-copy"><span>日常生活，有条不紊</span><h1>把生活安排好<br>把小确幸收进口袋</h1><p>权益、订阅与重要日子，都在这里。</p>${btn('查看可用权益','nav','primary','data-view="benefits"')}</div><figure class="campaign-art"><img src="/bank/assets/campaign22/life.webp" width="1200" height="800" alt="" loading="lazy"></figure></section><section class="bank-service-panel">${serviceGrid([['benefits','咖啡与出行','gift'],['subscriptions','订阅管理','subscriptions'],['plans','纪念日与活动','plans'],['tasks','自动预订','spark'],['bills','生活账单','bills']])}</section><div class="bank-home-columns"><section class="bank-editorial"><h2>我的生活安排</h2>${s.plans.filter(p=>['scheduled','ready','paused'].includes(p.status)).slice(0,4).map(p=>`<button class="bank-notice" data-action="nav" data-view="plans"><b>${date(p.at)}</b><span>${esc(businessCopy(p.title))}</span>${icon('arrow')}</button>`).join('')||'<p>还没有安排。为下一次旅行或纪念日创建一份计划。</p>'}${btn('管理生活计划','nav','','data-view="plans"')}</section><section class="bank-life-teaser"><h2>每次续费，心中有数</h2><p>查看订阅周期与绑定卡，开启提醒或取消授权。</p>${btn('查看订阅与代扣','nav','primary','data-view="subscriptions"')}</section></div>${benefits()}`;}
function personalHub(){const s=model.state,assets=s.balance+s.holdings.reduce((n,h)=>n+h.amount,0)+depositTotal(s)+assets39(s),count=model.notifications?.filter(n=>!n.read).length||0;return `<section class="bank-personal-hub"><div class="bank-personal-heading"><span class="recipient-avatar">${esc((s.profile?.name||'先生').slice(0,1))}</span><div><h1>${esc(s.profile?.name||'先生')}</h1><p>我的个人银行 · ${model.testMode?'体验账户':'个人账户'}</p></div>${btn('安全设置','nav','','data-view="security"')}</div><div class="bank-personal-shortcuts">${[['cards',s.cards.length,'银行卡'],['inbox',count,'待办消息'],['benefits',s.benefits.filter(b=>b.status==='available'&&b.expires>s.now).length,'可用权益'],['receipts',s.receipts.length,'交易回执']].map(([key,n,label])=>`<button data-action="nav" data-view="${key}"><strong>${n}</strong><span>${label}</span></button>`).join('')}</div><button class="bank-account-link" data-action="nav" data-view="accountOverview"><span>账户总览<small>余额、存款与理财本金合计</small></span><strong>${hideBalance?'••••••':'¥'+money(assets)}</strong>${icon('arrow')}</button><div class="bank-personal-spending"><h2>本月收支</h2><span>收入 <b>¥${hideBalance?'••••':money(model.report.income)}</b></span><span>支出 <b>¥${hideBalance?'••••':money(model.report.expense)}</b></span>${btn('查看收支明细','nav','','data-view="bills"')}</div></section>`;}
function wealthHeader(){return `<section class="bank-wealth-heading campaign-hero"><div class="campaign-copy"><span>财富管理</span><h1>让每笔资金<br>都有清晰的安排</h1><p>先完成风险评估，再比较期限、风险和起购金额。</p></div><figure class="campaign-art"><img src="/bank/assets/campaign22/wealth.webp" width="1200" height="800" alt="" loading="lazy"></figure><div class="bank-wealth-tabs" aria-label="理财产品分类">${[['all','全部产品'],['liquid','灵活期限'],['term','定期持有'],['low','较低风险']].map(([k,n])=>`<button data-action="wealthCategory" data-category="${k}" aria-pressed="${wealthCategory===k}">${n}</button>`).join('')}</div></section>`;}
function mobileBankNav(){return `<nav class="bank-mobile-tabs" aria-label="底部导航">${[['overview','首页','overview'],['invest','财富','invest'],['allServices','全部','cards'],['life','生活','gift'],['profile','我的','people']].map(([k,n,ico])=>`<button data-action="nav" data-view="${k}" ${(view===k||(k==='life'&&['stores','utilities','membership','bookings','mall','lifeOrders','benefits','plans','tasks'].includes(view))||(k==='invest'&&['gold','fx','deposits'].includes(view)))?'aria-current="page"':''}>${icon(ico)}<span>${n}</span></button>`).join('')}</nav>`;}

let recordQuery32='',recordStatus32='all',recordCard32='all';
function recordPanel32(page){
 const s=model.state,types={transfer:['transfer','ownTransfer','split','splitCollect'],invest:['buy','redeem','fundBuy','fundCancel','fundRedeem','fundSettlement'],gold:['buy','redeem'],subscriptions:['subscriptionCreate','subscription','subscriptionCard','subscriptionDetect'],plans:['event','birthday','planPayment','cancelPlan','workflow'],benefits:['benefit','parcelClaim','parcelCancel','parcelAdvance'],life:['bookingCreate','bookingCancel','bookingUse','parcelClaim','parcelCancel','parcelAdvance','lifeAccount','lifeAccountArchive','lifeTopup','lifeBuy','lifeBill','lifeUse','lifeRefund','lifeGift','lifeObserve','benefit','subscription','subscriptionCard','event','workflow']};
 let rows=businessRecords(s).filter(r=>!types[page]||types[page].includes(r.type));
 if(page==='cards')rows=rows.filter(r=>r.cardId===s.activeCardId||r.transactions.some(t=>t.cardId===s.activeCardId));
 if(page==='gold')rows=rows.filter(r=>(s.goldTrades||[]).some(t=>t.id===r.id));
 rows=rows.filter(r=>(recordCard32==='all'||r.cardId===recordCard32||r.transactions.some(t=>t.cardId===recordCard32))&&(recordStatus32==='all'||(recordStatus32==='attention'?['失败','需处理'].includes(recordState(r.status)):recordStatus32==='pending'?['待执行','待办理','已暂停','待确认份额','待使用','待发货','已发货'].includes(recordState(r.status)):recordState(r.status)===recordStatus32))&&(!recordQuery32||[r.title,r.id,...r.lines].join(' ').toLowerCase().includes(recordQuery32.toLowerCase())));
 return `<section class="panel business-records32"><div class="panel-title"><div><h2>办理记录与进度</h2>${btn('刷新记录','refreshRecords32')}<p>确认、执行与入账分别记录，失败不等于已扣款。</p></div></div><details class="record-filters32"><summary>筛选与搜索${recordQuery32?' · '+esc(recordQuery32):''}</summary><form data-form="recordSearch32" class="form-grid">${field('搜索业务或回执编号',`<input name="query" value="${esc(recordQuery32)}" maxlength="100" placeholder="转账、代扣、回执编号">`)}${field('办理状态',`<select name="status">${[['all','全部状态'],['pending','办理中 / 待使用'],['已完成','已完成'],['已确认份额','已确认份额'],['已核销','已核销'],['已收货','已收货'],['attention','失败 / 需处理'],['已取消','已取消']].map(([k,v])=>`<option value="${k}" ${recordStatus32===k?'selected':''}>${v}</option>`).join('')}</select>`)}${field('关联银行卡',`<select name="card"><option value="all">全部银行卡</option>${s.cards.map(c=>`<option value="${c.id}" ${recordCard32===c.id?'selected':''}>${esc(c.nickname)} · ${c.last4}</option>`).join('')}</select>`)}<button class="btn">查询记录</button></form></details><p>${rows.length} 条记录 · 历史记录缺少关联编号时不会猜测对应交易。</p>${rows.map(r=>`<details class="receipt-document"><summary><span><strong>${esc(businessCopy(r.title))}</strong><small>${stamp(r.at)}</small></span><span class="tag">${esc(recordState(r.status))}</span></summary><div class="record-body32"><p>业务编号 ${esc(r.id)}</p>${r.amount!=null?`<h3>办理金额 ¥${money(r.amount)}</h3>`:''}<ol>${r.lines.map(l=>`<li>${esc(businessCopy(l))}</li>`).join('')}</ol><h3>关联入账 ${r.transactions.length} 笔</h3>${r.transactions.map(t=>`<article><strong>${t.amount<0?'−':'+'}¥${money(Math.abs(t.amount))}</strong><p>${esc(t.merchant)} · 尾号 ${esc(s.cards.find(c=>c.id===t.cardId)?.last4||'—')} · ${stamp(t.at)}</p><small>${esc(t.id)}</small>${btn('下载交易回执','receiptDownload','',`data-id="${t.id}" data-kind="transaction"`)}</article>`).join('')||`<p>${r.linked?'当前无关联入账；预留预算、卡片设置、权益操作或失败记录不代表资金扣除。':'旧记录没有保存明确的入账关联，可在下方账本查询。'}</p>`}<div class="form-footer">${s.receipts.some(x=>x.id===r.id)?btn('下载操作回执','receiptDownload','',`data-id="${r.id}" data-kind="operation"`):''}${r.planId?btn('管理预约与计划','nav','',`data-view="plans"`):''}${r.workflowId?btn('查看自动执行步骤','nav','',`data-view="tasks"`):''}${r.subscriptionId?btn('管理代扣授权','nav','','data-view="subscriptions"'):''}${r.type==='failure'?btn('重新选择业务','nav','','data-view="allServices"'):''}</div></div></details>`).join('')||'<p class="empty">没有符合条件的记录，可调整筛选；新办理的业务会保留在这里。</p>'}</section>`;
}
function attachBusiness32(){
 if(view==='cards'){const box=document.createElement('section');box.className='panel account-statement32';box.innerHTML=cardStatement32();document.querySelector('#content .footer')?.before(box);}
 if(['receipts'].includes(view)){
  const panel=document.createElement('div');panel.id='business-records32';panel.innerHTML=recordPanel32(view);const footer=document.querySelector('#content .footer');if(view==='receipts')document.querySelector('#content .heading')?.after(panel);else footer?.before(panel);
 }
}
function showRedeem32(id){const h=model.state.holdings.find(x=>x.id===id);if(!h)return;const c=model.state.cards.find(x=>x.id===h.cardId);$('#confirm-body').innerHTML=`<form class="modal" data-form="redeem32" data-id="${esc(id)}">${flowSteps(0)}<h2>赎回安排</h2><p>${esc(model.products.find(x=>x.id===h.product)?.name)} · 持有本金 ¥${money(h.amount)}</p><p>返还 ${esc(c?.nickname)} · 尾号 ${esc(c?.last4)}；${h.fundUnits?'按份额及测试净值计算，扣除赎回费后到账，下一步核对净额。':'确认后按本金即时入账。'}</p>${h.unlock>model.state.now?`<p class="notice">尚在持有期，到期时间 ${stamp(h.unlock)}。</p>`:''}${field('赎回金额（元）',`<input name="amount" type="number" min="0.01" max="${h.amount/100}" step="0.01" value="${h.amount/100}" required>`,'可赎回部分或全部本金，确认前不会改变持仓。')}<p id="modal-error" class="error" role="alert"></p><div class="form-footer">${btn('返回','close')}<button class="btn primary" ${h.unlock>model.state.now?'disabled':''}>核对赎回</button></div></form>`;$('#confirm').showModal();}
function showSubscriptionCard32(id){const sub=model.state.subscriptions.find(x=>x.id===id);if(!sub)return;$('#confirm-body').innerHTML=`<form class="modal" data-form="subscriptionCard32" data-id="${esc(id)}"><h2>更换扣款卡</h2><p>${esc(sub.name)} · 每期 ¥${money(sub.amount)}</p>${field('新的扣款借记卡',`<select name="target">${model.state.cards.filter(c=>c.kind==='debit').map(c=>`<option value="${c.id}" ${sub.cardId===c.id?'selected':''}>${esc(c.nickname)} · ${c.last4} · ${c.status==='active'?'正常':'不可用'}</option>`).join('')}</select>`)}<p>不立即扣款，不改变现有授权状态，下期按新卡余额与限额检查。</p><p id="modal-error" class="error" role="alert"></p><div class="form-footer">${btn('返回','close')}<button class="btn primary">核对变更</button></div></form>`;$('#confirm').showModal();}
document.addEventListener('click',e=>{const d=e.target.closest('[data-action]')?.dataset;if(!d)return;if(d.action==='refreshRecords32')act({action:'init'});if(d.action==='subscriptionCard32')showSubscriptionCard32(d.id);if(d.action==='archiveContact32'){const c=model.contacts.find(x=>x.id===d.id);if(c)act({action:'contactArchive',id:c.id,archived:!c.archived},c.archived?'收款人已恢复':'收款人已停用，已有预约与历史记录保留');}});
document.addEventListener('submit',e=>{const f=e.target,d=Object.fromEntries(new FormData(f));if(f.dataset.form==='redeem32'){e.preventDefault();act({action:'prepare',operation:{type:'redeem',holding:f.dataset.id,amount:Number(d.amount)}});}if(f.dataset.form==='subscriptionCard32'){e.preventDefault();act({action:'prepare',operation:{type:'subscriptionCard',id:f.dataset.id,target:d.target}});}if(f.dataset.form==='recordSearch32'){e.preventDefault();recordQuery32=d.query.trim();recordStatus32=d.status;recordCard32=d.card;const panel=$('#business-records32');panel.innerHTML=recordPanel32(view);panel.scrollIntoView({block:'start'});}});

function cardStatement32(){const s=model.state,c=s.card,rows=s.transactions.filter(t=>t.cardId===c.id);return `<h2>${esc(c.nickname)} · 本卡流水</h2><p>尾号 ${c.last4} · ${c.kind==='credit'?'信用卡消费占用授信，还款从所选借记卡扣除。':`余额 ¥${money(c.balance)} = 可用 ¥${money(c.available)} + 预留 ¥${money(c.reserved)}`}。历史示例流水不作为初始余额的推算依据。</p>${rows.length?`<details><summary>查看 ${rows.length} 笔收支明细</summary>${rows.map(t=>`<article class="credit-row"><div><strong>${esc(t.merchant)}</strong><p>${stamp(t.at)} · ${esc(t.category)}</p></div><strong>${t.amount<0?'−':'+'}¥${money(Math.abs(t.amount))}</strong>${btn('查看交易回执','receiptDownload','',`data-id="${t.id}" data-kind="transaction"`)}</article>`).join('')}</details>`:'<p>本卡暂无交易，转入资金或完成业务后会显示。</p>'}`;}

function depositTotal(s){return (s.deposits||[]).filter(d=>d.status==='active').reduce((n,d)=>n+d.amount,0);}
function deposits(){const s=model.state;return title('存款与存单','开立、计息、支取与回执。')+`<section class="panel"><h2>持有本金 ¥${money(depositTotal(s))}</h2><p>测试利率，仅用于验证计息与记账，不代表银行报价。默认到期后停止计息、手动支取；可在下方单独授权到期续存一次。</p><form data-form="depositOpen33"><div class="form-grid">${field('扣款卡',`<select name="cardId">${s.cards.filter(c=>c.kind==='debit').map(c=>`<option value="${esc(c.id)}">${esc(c.nickname)} · ${c.last4}</option>`).join('')}</select>`)}${field('存入金额（元）','<input name="amount" type="number" min="50" max="1000000" step="0.01" required>')}${field('存期与测试年利率','<select name="term"><option value="30">30 天 · 1.00%</option><option value="90">90 天 · 1.20%</option><option value="180">180 天 · 1.50%</option></select>')}</div><button class="btn primary">核对存款</button></form></section><section class="panel"><h2>我的存单</h2>${(s.deposits||[]).map(d=>`<article class="retail-record"><div><strong>¥${money(d.amount)} · ${d.term} 天</strong><p>到期 ${stamp(d.maturesAt)} · ${d.status==='closed'?'已支取':d.maturesAt<=s.now?'已到期，待支取':'持有中'}</p><p>年利率 ${(d.bps/100).toFixed(2)}%${d.status==='closed'?' · 已付利息 ¥'+money(d.interest):''}</p><small>存单编号 ${esc(d.id)}</small></div>${d.status==='active'?btn(d.maturesAt<=s.now?'到期支取':'提前支取','depositClose33','',`data-id="${esc(d.id)}"`):btn('查看回执','nav','','data-view="receipts"')}</article>`).join('')||'<p>暂无存单。</p>'}</section><section class="panel"><h2>计息规则</h2><p>本金 × 年利率 × 完整持有天数 ÷ 365，向下取整至分。提前支取改按 0.10% 测试年利率，资金返还原卡。卡片不可用或限额不足时不扣款、不销单。</p></section>`;}
function aiControls33(){const a=model.state.ai,active=a?.expires>Date.now(),draft=a?.draft;return `<details class="ai-connect33"><summary>AI 连接与账务状态</summary><p>${model.cloudAI?(model.cloudProvider==='glm-free'?'GLM-5.3-Flash 体验接入，仅测试账户可用。共享队列按顺序处理，限流或过载后暂停5分钟；不设每日调用次数上限，按本站保守估算的 Token 额度保护。涉及扣款须单独确认。':'Cloudflare 云端模型已配置，仅测试账户可用。本站每日最多20次调用，达到上限停止，不自动切换其他模型。'):active?'已建立限时配对，请在本机运行助手。':'云端模型尚未启用。当前规则助手可用，本地模型可选。'}</p>${model.testMode?btn(active?'重新生成配对码':'生成本地配对码','aiPair33'):''}${active?btn('断开并使用规则助手','aiDisconnect33'):''}<a href="/bank/bank-local-agent.mjs" download>下载本地运行脚本</a><p>安装本地 Ollama 模型后，运行 node bank-local-agent.mjs，输入模型名称与配对码。首版仅连接测试账户；配对 15 分钟失效。</p><p>账务校验：${model.bookStatus?.balanced?'平衡':'未检查'} · ${model.bookStatus?.journals||0} 组分录</p></details>${a?.job?`<div class="ai-connect33"><p>处理状态：${esc(({queued:'等待本机接收',running:'本机正在解析',completed:'已返回',failed:'未完成'})[a.job.status]||a.job.status)}${a.job.expires<Date.now()?'（任务已过期）':''}</p>${btn('刷新结果','aiRefresh33')}${btn('取消需求','aiCancel33')}</div>`:''}${a?.sequence?`<div class="ai-connect33"><p>分步办理：第 ${a.sequence.index+1} / ${a.sequence.steps.length} 步，每步单独确认。</p>${a.sequence.waiting?btn(a.sequence.index===a.sequence.steps.length-1?'结束已完成计划':'准备下一步','aiNext39'):''}${btn('取消剩余步骤','aiCancel33')}</div>`:''}${draft?`<div class="ai-connect33"><strong>${esc(businessCopy(draft.title))}</strong>${draft.lines.map(x=>`<p>${esc(businessCopy(x))}</p>`).join('')}${btn('核对并打开确认单','aiAccept33','primary',`data-id="${esc(draft.id)}"`)}${btn('放弃草案','aiCancel33')}</div>`:''}`;}
document.addEventListener('click',async e=>{const d=e.target.closest('[data-action]')?.dataset;if(!d||busy)return;if(d.action==='depositClose33')act({action:'prepare',operation:{type:'depositClose',deposit:d.id}});if(d.action==='aiNext39')act({action:'aiNext'});if(d.action==='aiAccept33')act({action:'aiAccept',id:d.id});if(d.action==='aiRefresh33')act({action:'init'});if(d.action==='aiCancel33')act({action:'aiCancel'});if(d.action==='aiDisconnect33')act({action:'aiDisconnect'});if(d.action==='aiPair33'){await act({action:'aiPair'});if(model.pairToken){$('#confirm-body').innerHTML=`<section class="modal"><h2>连接你本机的模型</h2><p>配对码仅允许处理当前测试账户的需求，不允许确认交易。15 分钟有效，不要分享。</p><label>配对码<textarea readonly rows="3">${esc(model.pairToken)}</textarea></label><p>下载脚本并运行：<code>node bank-local-agent.mjs</code></p>${btn('关闭','close')}</section>`;delete model.pairToken;$('#confirm').showModal();}}});
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='depositOpen33')return;e.preventDefault();const f=new FormData(e.target);act({action:'prepare',operation:{type:'depositOpen',cardId:f.get('cardId'),amount:Number(f.get('amount')),term:Number(f.get('term'))}});});

