document.addEventListener('submit',e=>{const form=e.target,k=form.dataset.form;if(!['loanApply34','loanDraw34','installmentOpen34','financePay34'].includes(k))return;e.preventDefault();const f=new FormData(form);let operation;
 if(k==='loanApply34')operation={type:'loanApply',amount:Number(f.get('amount')),income:Number(f.get('income')),months:Number(f.get('months')),purpose:f.get('purpose'),cardId:f.get('cardId')};
 if(k==='loanDraw34')operation={type:'loanDraw',loan:form.dataset.id,agreed:f.get('agreed')==='on'};
 if(k==='installmentOpen34'){const entry=f.get('entry'),c=model.state.cards.find(c=>c.creditEntries?.some(e=>e.id===entry));operation={type:'installmentOpen',cardId:c?.id,entry,months:Number(f.get('months'))};}
 if(k==='financePay34')operation={type:form.dataset.kind+f.get('mode'),[form.dataset.kind==='loan'?'loan':'plan']:form.dataset.id,source:f.get('source')};
 act({action:'prepare',operation});});
