document.addEventListener('submit',e=>{const f=e.target;if(!['lifeBuy35','lifeBill35'].includes(f.dataset.form))return;e.preventDefault();const data=new FormData(f);act({action:'prepare',operation:{type:f.dataset.form==='lifeBuy35'?'lifeBuy':'lifeBill',store:f.dataset.store,biller:f.dataset.biller,source:data.get('source')}});});
document.addEventListener('click',e=>{const d=e.target.closest('[data-action="life35"]')?.dataset;if(d)act({action:'prepare',operation:{type:d.type,order:d.order,gift:d.gift}});});

document.addEventListener('input',e=>{if(e.target.id!=='life35-search')return;const q=e.target.value.trim().toLowerCase();let matches=0;document.querySelectorAll('.life35-stores>article').forEach(x=>{x.hidden=!x.textContent.toLowerCase().includes(q);if(!x.hidden)matches++;});document.querySelector('#life35-empty').hidden=matches>0;});

document.addEventListener('submit',e=>{const f=e.target,k=f.dataset.form;if(!['lifeAccount36','lifeBill36','lifeTopup36'].includes(k))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));act({action:'prepare',operation:{...data,type:k==='lifeAccount36'?'lifeAccount':k==='lifeBill36'?'lifeBill':'lifeTopup',biller:f.dataset.biller||data.biller,...(k==='lifeTopup36'?{amount:Number(data.amount)}:{})}});});
document.addEventListener('click',e=>{const d=e.target.closest('[data-action="life36"]')?.dataset;if(d)act({action:'prepare',operation:{type:d.type,accountId:d.accountId}});});
function filterLife36(){const q=document.querySelector('#life36-query')?.value.trim().toLowerCase()||'',status=document.querySelector('#life36-status')?.value||'all';let n=0;document.querySelectorAll('[data-life-order]').forEach(x=>{x.hidden=!(x.textContent.toLowerCase().includes(q)&&(status==='all'||x.dataset.status===status));if(!x.hidden)n++;});const empty=document.querySelector('#life36-empty');if(empty)empty.hidden=n>0;}
document.addEventListener('input',e=>{if(e.target.id==='life36-query')filterLife36();});document.addEventListener('change',e=>{if(e.target.id==='life36-status')filterLife36();});

document.addEventListener('submit',e=>{const f=e.target;if(f.dataset.form!=='service37')return;e.preventDefault();const data=Object.fromEntries(new FormData(f));for(const k of ['amount','days'])if(k in data)data[k]=Number(data[k]);act({action:'prepare',operation:{...data,type:f.dataset.type,...(f.dataset.cardId?{cardId:f.dataset.cardId}:{}),...(f.dataset.entry?{entry:f.dataset.entry}:{}),...(f.dataset.caseId?{caseId:f.dataset.caseId}:{})}});});
document.addEventListener('click',e=>{const d=e.target.closest('[data-action="service37"]')?.dataset;if(d)act({action:'prepare',operation:{type:d.type,caseId:d.caseId,workflow:d.workflow,step:d.step}});});

document.addEventListener('click',e=>{if(e.target.closest('[data-action="sessions37"]'))act({action:'sessions'});});
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='revokeSessions37')return;e.preventDefault();const f=new FormData(e.target);act({action:'revokeOtherSessions',pin:f.get('pin'),otp:f.get('otp')});});

document.addEventListener('click',e=>{const d=e.target.closest('[data-action="renewal38"]')?.dataset;if(d)act({action:'prepare',operation:{type:'depositRenewal',deposit:d.deposit,mode:d.mode}});});

document.addEventListener('submit',e=>{const f=e.target;if(f.dataset.form!=='closure39')return;e.preventDefault();const data=Object.fromEntries(new FormData(f));if('amount' in data)data.amount=Number(data.amount);act({action:'prepare',operation:{...data,type:f.dataset.type}});});
document.addEventListener('click',e=>{const d=e.target.closest('[data-action="closure39"]')?.dataset;if(d)act({action:'prepare',operation:{type:d.type,order:d.order,caseId:d.caseId}});});

installCommerce41({getModel:()=>model,api,update:m=>{model=m;render();},esc,money,stamp,toast,isBusy:()=>busy,setBusy:v=>{busy=v;}});

window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search).get('page');view=navs.some(n=>n[0]===p)?p:'overview';if(model)render();});

function legacyDeposit42(){const rows=model.state.holdings.filter(h=>h.product==='deposit');return rows.length?`<section class="panel"><h2>历史存款体验持仓</h2><p>旧版存款仍保留原本金与到期规则，可在这里支取。</p>${rows.map(h=>`<article><strong>¥${money(h.amount)}</strong><p>${stamp(h.unlock)} 到期</p>${btn('核对支取','redeem','',`data-id="${esc(h.id)}"`)}</article>`).join('')}</section>`:'';}

installFlights43({getModel:()=>model,render,act});

document.addEventListener('submit',e=>{const f=e.target;if(f.dataset.form!=='lifeMall61')return;e.preventDefault();act({action:'prepare',operation:{type:'lifeMall',sku:f.dataset.sku,source:new FormData(f).get('source')}});});
document.addEventListener('change',e=>{const f=e.target.closest('form[data-form=lifeTopup36]');if(!f||e.target.name!=='amount')return;const host=f.querySelector('[data-payment61]');const selected=f.querySelector('[name=source]:checked')?.value;host.innerHTML=lifeCards61(model.state.cards,Number(e.target.value)*100,esc);const old=[...host.querySelectorAll('[name=source]')].find(x=>x.value===selected&&!x.disabled);if(old)old.checked=true;});

document.addEventListener('click',e=>{const d=e.target.closest('[data-action=aiNavigate62]')?.dataset;if(d){assistantOpen=false;navigateBank(d.view);render();}});

document.addEventListener('submit',e=>{if(e.target.dataset.form!=='lifestyle64')return;e.preventDefault();const f=new FormData(e.target),settings=Object.fromEntries(f);for(const k of ['enabled','birthdays','bills'])settings[k]=f.has(k);act({action:'saveLifestyle64',settings},'生活偏好与授权已保存');});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;if(b.dataset.action==='dismiss64')act({action:'dismiss64',id:b.dataset.id});if(b.dataset.action==='deleteLifestyle64')act({action:'deleteLifestyle64'},'生活资料与授权已删除');});

document.addEventListener('click',e=>{if(e.target.closest('[data-add-date65]')){const list=document.querySelector('[data-date-list65]');if(list.children.length>=20){toast('最多保存20项重要日期');return;}list.insertAdjacentHTML('beforeend',dateRow65({},esc));list.lastElementChild.querySelector('input').focus();}if(e.target.closest('[data-remove-date65]'))e.target.closest('.date-row65').remove();});
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='preferences65')return;e.preventDefault();const f=e.target,d=new FormData(f);const month=d.get('birthdayMonth'),day=d.get('birthdayDay');if(Boolean(month)!==Boolean(day)){toast('请选择完整的生日月份和日期');return;}const rows=[...f.querySelectorAll('.date-row65')];const dates=[];for(const row of rows){const name=row.querySelector('[data-date-name]').value.trim(),m=row.querySelector('[name=Month]').value,day=row.querySelector('[name=Day]').value;if(!name||!m||!day||name.includes('|')){toast('请填写每项日期的名称、月份和日期');row.open=true;return;}dates.push(name+'|'+m+'-'+day);}const settings={city:d.get('city'),birthday:month?month+'-'+day:'',artists:d.get('artists'),interests:[...d.getAll('interest'),d.get('customInterests')].filter(Boolean).join('、'),budget:0,dates:dates.join('\n')};for(const k of ['enabled','birthdays','bills'])settings[k]=d.has(k);act({action:'saveLifestyle64',settings},'偏好已保存');});

document.addEventListener('submit',e=>{if(e.target.dataset.form!=='journey66')return;e.preventDefault();act(Object.fromEntries(new FormData(e.target)));});

document.addEventListener('click',e=>{const b=e.target.closest('[data-action="planFromDate67"]');if(!b)return;navigateBank('plans');const f=document.querySelector('form[data-form="journey66"]');if(!f)return;f.closest('details').open=true;f.elements.kind.value='birthday';f.elements.name.value=b.dataset.name;f.elements.start.value=b.dataset.date;f.elements.end.value=b.dataset.date;f.elements.place.value=model.state.lifestyle?.city||'';f.elements.budget.focus();});
